quests[85066] = { id = 85066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen", description = "Einfallende Dämonen und Todesrituale! Das klingt alles ziemlich gruselig. Glücklicherweise macht diese kleine Zeitblase, in der wir gerade stehen, es einfach, uns mit einem spezifischem Zeitpunkt zu verbinden.\n\nDoch das wird nicht gerade ungefährlich. Gebt mir Bescheid, sobald Ihr und Euer Freund bereit seid.", sourceObjective = "Sprecht mit Gregory in Andorhal und bittet ihn, Euch zum Brand von Andorhal zu begleiten.", completion = "Dann passiert es wirklich... \n\nSo sehr es mir auch missfällt, muss ich doch gestehen, dass ich vermutlich nicht die beste Person bin, um Euch zurückzubegleiten. Mein Körper hat durch das heilige Feuer von Aeonas und den Dämonenangriff einfach zu viel Schaden genommen. In meinem aktuellen Zustand halte ich Euch eher zurück, als Euch eine Hilfe zu sein. Und nach dem Tod von Ada brauchen wir vermutlich Hilfe von außen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85067] = { id = 85067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Paladin der Silbernen Hand", description = "Ich habe gesagt, dass ich nicht ans Schicksal glaube, doch ich bin mir nicht ganz sicher, ob das ganz der Wahrheit entsprach. Meine Sichtweise hat sich so sehr verändert, seitdem mein sterbliches Leben sein Ende fand, doch je länger ich auf dieser Mission verbringe, desto mehr erkenne ich Muster und Verbindungen in Dingen. Ich glaube, Ihr wisst es bereits, doch es ist Aeonas, der mit Euch gehen muss.\n\nGlaubt mir, wenn ich Euch sage, dass ich nichts lieber tun würde, als meinem alten Freund seinen Frieden zu lassen, doch das ist größer, als es mir lieb ist. Begebt Euch zu Uthers Grabmal und erklärt die Situation.", sourceObjective = "Begebt Euch zu Uthers Grabmal und erklärt Aeonas die Situation.", completion = "<Gregory nickt erst Euch und dann Aeonas zu.>\n\nEs wird Zeit. Sprecht mit Chromie, sobald Ihr bereit seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85068] = { id = 85068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sagt, es gäbe keinen Weg zurück?", description = "Das Portal ist bereit.\n\nSobald Ihr eintretet, werdet Ihr zu Andorhal kurz nach dessen Fall transportiert. Damit Ihr nicht so herausstecht, habe ich ein paar magische Verkleidungen für Euch vorbereitet. Die sollten für die meisten Bewohner der Vergangenheit ausreichen, doch Ihr solltet dennoch vorsichtig vorgehen und versuchen, unbemerkt zu bleiben. Sobald Ihr habt, was Ihr braucht, müsst Ihr in der Vergangenheit nur noch an diesen Ort zurückkehren. Das Portal sollte dort auf Euch warten.", sourceObjective = "Nehmt das Portal zum Brand von Andorhal.", completion = "Wir haben es geschafft. Macht Euch auf alles gefasst, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85074] = { id = 85074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Brand von Andorhal", description = "Ich bin mir nicht sicher, was uns dort drinnen erwartet, aber es wird nicht angenehm.\n\nWir müssen da rein, den Ort ausfindig machen, an dem Uther fiel, und ein paar Tropfen seines Blutes sammeln. Anschließend müssen wir uns einen Weg zurück zum Gasthaus auf der westlichen Seite der Stadt bahnen und entkommen. Wir sollten uns beeilen, doch wir müssen auch mit Respekt und Sorgfalt an die Sache herangehen, wie es meinem Lord Uther gebührt. Der Gedanke, ihn an dem Ort zu stören, an dem er sein Leben ließ, ist für mich zutiefst unangenehm.\n\nBringen wir das hinter uns.", sourceObjective = "Erreicht Euer Ziel und entkommt dem Brand von Andorhal.", progress = "So unappetitlich das auch war, wir haben das getan, weswegen wir hergekommen sind.", completion = "Ich vermute, dass wir nicht damit rechnen können, dass die Verkleidungen zurückkommen, daher bleibt uns wohl keine andere Wahl, als uns hier raus zu kämpfen. Macht Euch bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85087] = { id = 85087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Flucht", description = "Die Untoten sind durchgebrochen und haben die Westseite der Stadt befallen. Das wird ein harter Kampf, {name}. Die Zeit sitzt uns jetzt im Nacken, daher sollten wir die Gebiete mit den größten Zahlen der Geißel vermeiden.\n\nOh, fast hätte ich es vergessen, nehmt das. Wenn wir aus irgendeinem Grund voneinander getrennt werden, dann lasst dieses Horn ertönen. So sollte ich wieder zu Euch finden.", sourceObjective = "Kämpft Euch einen Weg zum Gasthaus und entkommt zurück in Eure eigene Zeit. Wenn Ihr von Aeonas getrennt werdet, dann lasst das befleckte Horn ertönen, um ihn wieder an Eure Seite zu rufen.", progress = "Es ist... nichts, nur ein Kratzer. Ich muss nur erst einmal zu...", completion = "<Aeonas dämmert allmählich weg, als seine Augen sich plötzlich wieder öffnen und Euch anblicken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[85090] = { id = 85090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Zukunft", description = "<Aeonas zuckt zusammen. Er ist schwer verletzt.> Ich glaube... weiter schaffe ich es nicht, {name}. Es ist... okay. Das hier... war immer, wo ich hätte sein sollen. Ich bin froh, hier zu sein... mit meinen Freunden... am Ende.\n\nHier, nehmt das. Ich habe es geschmiedet... um mich zu erinnern. Um sicherzustellen, dass ich niemals die Freunde vergesse, die ich hier verlor, und dass ich ihnen stets treu bleibe... Wahrheitsbringer.\n\nTut mir den Gefallen und übergebt ihn Gregory. Vielleicht hilft er ihm dabei, sich daran zu erinnern, wer er ist. Euch ist es, denke ich, auch schon aufgefallen... er hat sich... verändert...\n\nIch...", sourceObjective = "Nehmt das Portal zurück in Eure Zeit und übergebt den Wahrheitsbringer an Gregory.", progress = "Wo ist Aeonas? Was ist passiert?", completion = "Erzählt mir alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[85091] = { id = 85091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Sieges", description = "Danke... dass Ihr mir das gebracht habt. Die Klinge ist geweiht und wird mir beim Führen beträchtlichen Schmerz zufügen, doch das ist ein kleines Opfer für... meinen Freund.\n\nWir können später trauern. Jetzt müssen wir all dem ein Ende setzen. Versammelt Eure treusten Verbündeten und begebt Euch zum Demonfall-Canyon. Azgaloth wird sich Euch möglicherweise nicht sofort offenbaren, aber wenn Ihr eine angemessene Herausforderung aussprecht, wird er antworten.\n\nNehmt das Blut und verwendet es, um Eure Waffe zu weihen und ihn zu vernichten. Für Aeonas und Ada. Es wird Zeit, das zu beenden.", sourceObjective = "Weiht Eure Waffe mit dem Blut des Lichtbringers und besiegt Azgaloth im Demonfall-Canyon.", completion = "Meine Mission ist endlich abgeschlossen.\n\nDas hat mich so lange beschäftigt, dass ich noch gar nicht richtig begriffen habe, was der Sieg wirklich bedeutet. Ich schätze, er bedeutet, dass unsere Allianz zu Ende geht und ich mich zurück auf den Weg nach Northrend machen sollte...\n\n<Eine unangenehme Stille breitet sich zwischen Euch aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[85092] = { id = 85092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrheitsbringer", description = "Aeonas hat dies schon lange vor mir realisiert. Er hat gesehen, wie ich mich auf dieser Mission verändert habe. Tatsächlich fühle ich... Traurigkeit, Reue... und wieder Liebe. Traurigkeit wegen Ada, Reue wegen meines Betrugs und Liebe für meinen Freund. Ich weiß nicht genau, was das bedeutet, aber ich weiß, dass ich nicht nach Northrend zurückgehen kann.\n\nVielleicht nach Lordaeron? Vielleicht gibt es dort andere wie mich. Andere, die sich vom Licht abgewendet haben... und langsam wieder ihren Weg zurück finden. Vielleicht kann ich ihnen helfen, wie mein Freund auch mir geholfen hat.", sourceObjective = "Verabschiedet Euch von Gregory.", completion = "Die Tatsache, dass ich keine Schmerzen mehr verspüre, wenn ich Wahrheitsbringer halte, verrät mir, dass ich alles über den Pfad weiß, den ich nun beschreiten muss.\n\nIch glaube allerdings, dass die Klinge bei Euch bleiben sollte. Aeonas würde das verstehen, und ich bin sicher, er würde das gutheißen. Der größte Teil meiner kämpferischen Tage liegt wohl hinter mir, und eine Waffe wie diese verdient es, im Dienste des Lichts eingesetzt zu werden.\n\nLebt wohl, {name}. Möge das Licht mit Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[85112] = { id = 85112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erschöpfte Sense", description = "Die Sense ist verdreht und strahlt eine dämonische Aura aus. Dennoch fühlt sie sich spröde an und Ihr habt Angst, dass sie bei Nutzung zerbrechen würde. Sie zerrt an Eurer Energie, als würde sie Euch auf die Probe stellen. Ein unbändiger Hunger regt sich tief in Euch, wenn Ihr nur an die Sense denkt. Vielleicht weiß jemand mit Kenntnissen über dämonische Artefakte mehr darüber.", sourceObjective = "Bringt den Stab zu Doan Karhan im Brachland.", completion = "Ihr habt da ein wirklich bemerkenswertes Artefakt gefunden, {name}. Ich glaube, dass dieser Stab noch gerettet werden kann... aber das verlangt einiges an Arbeit. \n\nHmm, das könnte auch ein hervorragender Kandidat für ein paar offene Angelegenheiten sein, die wir noch erledigen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85150] = { id = 85150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ein toter Käfer ist ein guter Käfer", description = "Die Silithiden verändern sich ständig, und aufeinanderfolgende Generationen nehmen neue Eigenschaften an, um ihre Überlebensfähigkeit zu verbessern. Wir haben nördlich von hier, in der Nähe des Baus des Ashischwarms, eine neue Art von Silithidfliegern entdeckt. Es sind Flieger, die einigen anderen Silithidwespen ähneln, aber sie sind kleiner, schneller und haben ein blaues Exoskelett.\n\nIch will wissen, ob von diesen Flitzern Gefahr ausgeht. Erledigt ein paar von ihnen und berichtet, wie stark sie sind.", sourceObjective = "Findet und besiegt 4 Silithidflitzer. Das sind schnelle, kleine Silithidwespen mit einem blauen Exoskelett.", sourceObjectiveStatus = "unverified-source-field" }
quests[85248] = { id = 85248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeder weiß, dass Käfer nicht fliegen können", description = "Aus Euren Berichten geht hervor, dass die Flitzer definitiv schneller sind, aber wir müssen mehr über sie wissen. Wenn wir einen studieren können, finden wir vielleicht heraus, wie wir sie effektiver neutralisieren können.\n\nMit Euren Jagdfähigkeiten sollte es möglich sein, einen der Flitzer kampfunfähig zu machen und ihn hierher zurückzubringen, damit wir mehr über ihn erfahren können. Spürt einen auf, verwundet ihn, fesselt ihn und bringt ihn hierher in den Käfig, den wir für Studienzwecke aufgestellt haben.", sourceObjective = "Kämpft gegen einen Silithidflitzer, bis er geschwächt ist, setzt dann Eure Fähigkeit 'Erschütternder Schuss' ein, um ihn zu verlangsamen. Sollte er in Raserei verfallen, macht ihn mit 'Einlullender Schuss' bewusstlos. Fesselt ihn, schleppt ihn zur Burg Cenarius zurück und sichert ihn für weitere Untersuchungen am Anbindepfosten vor dem Kriegsraum von Kommandant Mar'alith.\n\nKehrt zu Kommandant Mar'alith in der Burg Cenarius zurück, wenn Ihr fertig seid.\n\nIhr erlernt 'Einlullender Schuss' während des Schlachtzugs im Geschmolzenen Kern.", sourceObjectiveStatus = "unverified-source-field" }
quests[85250] = { id = 85250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begegnung mit der Menagerie", description = "Während Ihr unterwegs wart, hat uns ein Irrwisch besucht und nach Euch gesucht. Der Irrwisch gab an, dass Ihr im Krater von Un'Goro gebraucht werdet. Der Irrwisch sagte, dass einer Eurer Gefährten den Aufenthaltsort eines Feindes entdeckt hat, den Ihr schon seit einiger Zeit verfolgt.\n\nNochmals vielen Dank für Eure Hilfe hier. Wie es scheint, ist es für Euch an der Zeit, weiterzuziehen.", sourceObjective = "Reist zum Krater von Un'Goro im Süden von Kalimdor und sucht dort nach Hinweisen zu Van Amburgh.", sourceObjectiveStatus = "unverified-source-field" }
quests[85251] = { id = 85251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidungskampf im Krater von Un'Goro", description = "Endlich ist es so weit. Es hat mich alles gekostet, das Lager von Van Amburgh hier zu finden. Zudem war ich noch durch eine seiner Fallen verwundet. Er hat seine Bestien bei sich. Seid Ihr bereit, dies zu beenden?", sourceObjective = "Reist zum Lager von Van Amburgh im Un'Goro-Krater im Süden von Kalimdor und besiegt den Zwerg und seine Menagerie.", sourceObjectiveStatus = "unverified-source-field" }
quests[85304] = { id = 85304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz des Feuers", description = "Die Schriftrolle strahlt ungleich allen anderen, die Ihr gefunden habt, eine feurige Energie aus. In der Nähe von Draco'dar in der Brennenden Steppe gibt es einen magischen Stein, der den Zweck der Schriftrolle offenbaren könnte. Übersetzt die Rolle und erlernt ihren Zweck, bevor Ihr Eure Erkenntnisse den Bibliothekaren von Stormwind oder Undercity mitteilt.", sourceObjective = "Findet heraus, was es mit der ungewöhnlichen Schriftrolle auf sich hat, und teilt Eure Erkenntnisse mit einem Bibliothekar in Stormwind oder Undercity.", completion = "Da habt Ihr etwas wirklich Interessantes gefunden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85385] = { id = 85385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Bibliothekars", description = "Eure Entdeckung der Essenz des Feuers hat unser Wissen über das Arkane stark erweitert. Ich habe Gerüchte über eine ähnliche Macht in Winterspring gehört, allerdings ist sie von frostiger Natur. Mein Partner in der Ewigen Warte wird mehr Informationen darüber haben.", sourceObjective = "Sprecht mit Valxx Cracklequil in der Ewigen Warte, um mehr über die Gerüchte zu erfahren.", completion = "Die alten Käuze aus der Bibliothek haben Euch also geschickt, was? Sie mögen mich nicht besonders. Sie behaupten, dass Schießpulver und Magie nicht zusammenpassen. Pah. \n\nJa, ich weiß ein oder andere über das, wonach Ihr fragt. Glücklicherweise bin ich zu beschäftigt, um mich selbst darum zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[85386] = { id = 85386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz des Frosts", description = "Vor einiger Zeit hörte ich von seltsamen Vorgängen in der Frosthauchschlucht. Es scheint, als hätten diese Eisriesen eine alte Macht gefunden. Ich würde selbst nachforschen, aber ich bin hier zu beschäftigt. Bringt mir alles Interessante mit, ja? Das heißt, falls Ihr lebendig zurückkehrt.", sourceObjective = "Untersucht die Frosthauchschlucht nach einer mysteriösen Frostmacht.", completion = "Was ist denn das? Da unten war tatsächlich etwas?! Ich bin überrascht, dass diese Eisriesen Euch nicht in einen Eiszapfen verwandelt haben, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[85388] = { id = 85388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schändliche Störung", description = "Während Eurer Abwesenheit habe ich gehört, dass drüben in Mazthoril etwas Übles vor sich geht. Das scheint Euer Ding zu sein, also seht zu, was Ihr tun könnt, um es zu lösen. Diese blauen Drachen kennen sich gut mit dem Arkanen aus, vielleicht geben sie Euch ja etwas dafür.", sourceObjective = "Gebietet der Verderbnis in Mazthoril Einhalt.", progress = "Ihr seid noch nicht tot? Interessant.", completion = "Ihr habt mir sehr geholfen, {name}. Auch wenn ich fürchte, dass es im Vergleich zu den Heldentaten, die Ihr für uns vollbracht habt, verblasst, möchte ich Euch dies geben. Dieser Stab ist unvollständig, kann aber vielleicht wiederhergestellt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[85401] = { id = 85401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das eisige Grab", description = "Genau wie Leben aus dem Verfall entspringt, so mag auch das Unnatürliche dem Natürlichen dienen können.\n\nDas Herz kann in einem Stab von wechselnder Gestalt umgewandelt werden, aber ich brauche ein Gefäß, das stark genug ist, seine Macht aufzunehmen.\n\nEs gibt in Winterspring in der Nähe von Starfall einen Grabhügel. Der echte Eingang offenbart sich nur, wenn Ihr alleine seid.\n\nDarin befindet sich ein Bewahrer, der vor langer Zeit vom Weg abgekommen ist: Nandieb. Sein Stab soll das Gefäß für das Herz werden. Es schmerzt mich, dies vorzuschlagen, aber er ist nicht mehr der große Bewahrer, den ich einst kannte.", sourceObjective = "Findet Nandieb im Grabhügel in der Nähe von Starfall in Winterspring und bergt seinen Stab. Ihr müsst dies alleine erledigen.", progress = "Habt Ihr den Stab bekommen?", completion = "Das chromatische Herz und Nandiebs Stab: Zusammen bilden sie die wechselnden Stäbe Gla'sir und Rae'lar. Zwei Objekte der Bösartigkeit und der Zerstörung, transformiert für den Dienst an Schöpfung und Leben.\n\nIch verleihe Euch diese Macht, {name}, in der Hoffnung, dass Ihr Euch weiterhin als ehrenhafte Verwalterin allen Lebens auf Azeroth erweist.", sourceObjectiveStatus = "unverified-source-field" }
quests[85441] = { id = 85441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donneraan der Windsucher", description = "Ich habe Euch alles gesagt, was ich weiß, {name}. Es ist nun Eure Aufgabe Elementium zu finden. Ihr seid es, der die körperliche Form des Feuerfürsten zerstören muss.\n\nGewinnt dadurch den Segen von Donneraan.", sourceObjective = "Um die Macht des Windsuchers zu nutzen, müsst Ihr Hochlord Demitrian im Kristalltal die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85442] = { id = 85442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Gefäßes", description = "Untersucht das Gefäß, mit dem der flüchtige Sturm ausgelöst wurde. Aus diesem wurde der Windsucher wiedergeboren, der nun neue Kraft aus dem Kristalltal schöpft.", sourceObjective = "Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian.", sourceObjectiveStatus = "unverified-source-field" }
quests[85443] = { id = 85443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerzorn erwache!", description = "Ihr habt den Windsucher bezwungen. Nehmt die schlummernde Klinge und zwingt den Anhänger, Demitrian, die Materialien einzusetzen, um Donnerzorn zu erwecken.", sourceObjective = "Präsentiert Hochlord Demitrian die schlummernde vom Wind berührte Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[85445] = { id = 85445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die goldene Scheibe", description = "Ihr habt keine Ahnung, was dieser Gegenstand sein könnte, aber es ist eindeutig ein Artefakt von großer Macht. Ihr solltet jemanden finden, der Euch mehr über dieses Artefakt und seinen wahren Zweck sagen kann.", sourceObjective = "Findet jemanden, der Euch etwas zur schimmernden goldenen Scheibe erzählen kann.", progress = "Bitte beeilt Euch, {name}.", completion = "Wartet, was habt Ihr da? Das sieht aus wie... Nein, das kann nicht sein. Ich habe es nur in Büchern gesehen, aber... es wurde zerstört. Das ist doch nicht...\n\n<Gareks Fixierung auf den Gegenstand an Eurem Gürtel wird kurz unterbrochen und seine Augen treffen die Euren.>\n\nWoher habt Ihr diesen Gegenstand, {class}? Bitte, erzählt mir alle Details!", sourceObjectiveStatus = "unverified-source-field" }
quests[85446] = { id = 85446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppe des Drachenlords", description = "<Riosus lauscht, während Ihr Eure Geschichte erzählt.>\n\nJa, Garek hatte Recht, dies ist nicht die wahre Drachenseele... und den Titanen sei Dank. Hielte <ein minderbemittelter Sterblicher/eine minderbemittelte Sterbliche> wie Ihr ein so mächtiges Artefakt in Händen, wäre ich kaum zuversichtlicher als hätte es der Herrscher des Blackrock selbst. Trotzdem ist es gefährlich, und wir sollten uns um seine Beseitigung kümmern. Die ursprüngliche Drachenseele war nicht leicht zu zerstören. Kommt, lasst uns über die Möglichkeiten zur Beseitigung dieses geringeren Simulakrums sprechen.", sourceObjective = "Sprecht mit Riosus und entwerft einen Plan, wie Ihr das Simulakrum der Drachenseele loswerden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85447] = { id = 85447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Batol", description = "Nefarian experimentiert schon lange mit den fünf Drachenschwärmen, und es scheint, dass dieses 'Simulakrum' der Drachenseele ein solches Experiment war. Ich erschaudere bei dem Gedanken, was passieren könnte, wenn es ihm gelingt, auch nur einen Bruchteil der Macht der wahren Drachenseele zu emulieren. Bitte, sucht Agenten der roten Drachen in der Nähe der Ruinen von Grim Batol auf. \n\nIch werde das Simulakrum verzaubern, um Euch als Freund des roten Schwarms zu kennzeichnen.", sourceObjective = "Bringt das Simulakrum der Drachenseele zum Anführer der Drachenschar in der Nähe des Eingangs zur Festung von Grim Batol.", progress = "Wer bist du, und wie kannst du es wagen, vor mich zu treten, Sterblicher?", completion = "Ihr tragt das Zeichen eines Agenten von Korialstrasz, aber als Fremder habe ich dennoch keine andere Wahl, als Euch zu misstrauen, Sterblicher. Ob mit oder ohne Zeichen, ich rate Euch, vorsichtig zu sein, damit ich Euch nicht von meinen Drachkin rösten und verschlingen lasse.", sourceObjectiveStatus = "unverified-source-field" }
quests[85453] = { id = 85453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine gute Tat bleibt unbestraft", description = "Und damit, fürchte ich, habt Ihr Eure Nützlichkeit verloren. Aber keine Sorge, ich würde nicht davon träumen, Eure Dienste unbelohnt zu lassen. Lasst mich Euch die Ehre erweisen, von meiner wahren Gestalt verschlungen zu werden. Das ist wahrhaftig eine Ehre, {class}.", sourceObjective = "Verteidigt Euch gegen Riosustrasz!", sourceObjectiveStatus = "unverified-source-field" }
quests[85454] = { id = 85454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine faire Belohnung", description = "Ihr habt viel getan, um unsere Brut zu verteidigen, {class}. Es scheint mir passend, Euch mit einem Geschenk zu entlohnen, mit dem Ihr auch in Zukunft andere verteidigen könnt. Sprecht mit mir, sobald Ihr bereit seid, dann zerstören wir diese falsche Drachenseele gemeinsam. Ich glaube, dass ich mir einen Teil der Energie, die freigesetzt wird, während die Magie des Simulakrums sich verflüchtigt, zunutze machen kann, um zusammen mit einem Teil meiner eigenen Magie etwas Besonderes für Euch zu schaffen.", sourceObjective = "Sprecht mit Krasus, um das Simulakrum der Drachenseele zu zerstören und Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[85455] = { id = 85455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut des Lichtbringers", description = "Eure Hand zittert leicht, während Ihr die kleine Phiole mit Blut haltet. Abgesehen von der Inschrift auf dem Etikett, könnt Ihr eine Wärme und Energie spüren, die von der Probe ausgestrahlt wird. Könnte das wirklich das Blut Uthers des Lichtbringers, des legendären Helden, sein? Ihr solltet jemanden finden, der die Authentizität dieser Probe bestätigen kann.", sourceObjective = "Findet jemanden, der Euch mehr über das Blut des Lichtbringers erzählen kann. \n\n(Hinweis: Zunächst muss die Quest \"Pestlandtreffen\" abgeschlossen werden, damit diese Quest abgegeben werden kann.)", progress = "Friede sei mit Euch, {class}.", completion = "Wartet, was habt Ihr da?\n\n<Die Augen von Hohepriester Thel'danis weiten sich, während er das Reliquiar untersucht.>\n\nDas kann doch nicht sein, oder? Wie sollten die schwarzen Drachen an eine Probe von Lord Uthers Blut gelangen?\n\nWenn sie sich als echt herausstellen sollte, wäre das ein Relikt unfassbarer Bedeutung. Lasst uns mehr darüber sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85457] = { id = 85457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau das Richtige", description = "Ich sehe schon, Ihr wollt das Blut zu Gregory bringen. Gut. Mein Urteil war bestenfalls fragwürdig und es war schon immer das Spiel eines jüngeren Paladins, auf das ich mich eingelassen habe.\n\nIch bin mir nach wie vor nicht sicher, wie ich mich fühlen soll, aber ich bin auf jeden Fall froh, zu sehen, dass Ihr zu dem Paladin herangewachsen seid, der Ihr schon immer sein solltet.", sourceObjective = "Bringt das Blut des Lichtbringers zu Gregory nach Caer Darrow in den Westlichen Pestländern.", progress = "Ja, {name}?", completion = "Ich hatte nicht erwartet, Euch hier wiederzusehen, zumindest nicht so schnell. Was gibt es?", sourceObjectiveStatus = "unverified-source-field" }
quests[85458] = { id = 85458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flüsternde Schlucht", description = "Das ist... unglaublich. Ich bin viel zu pragmatisch, um an Schicksal zu glauben, doch das ist durchaus mal eine glückliche Wende des Schicksals. Damit sollten wir alles haben, was wir zur Vervollständigung des Rituals und endgültigen Vernichtung der Kugel benötigen. Doch wie bei jedem guten Ritual, kommt es auf den Ort an. Sagt Euch die Flüsternde Schlucht in Winterspring etwas? Das ist ein verfluchter, dämonenverseuchter Ort, doch genau dort müssen wir das zu Ende führen.\n\nIch schnappe mir die Kugel und die verbleibenden Materialien und treffe Euch dort. Meine Mission hat bald ein Ende!", sourceObjective = "Trefft Gregory in der Flüsternden Schlucht in Winterspring.", progress = "Ihr habt es geschafft, gut. Seid auf der Hut, {name}.", completion = "Ich weiß, dass das etwas abseits des Weges ist, doch wir brauchen einen Ort, wo die Barriere zwischen unserer Realität und dem Nether dünn ist und eine hohe Konzentration an latenter Arkanenergie vorliegt. Wir haben uns für den Teufelswald aufgrund seiner Nähe zum Hyjal entschieden. Bei diesem Ritual werde ich nichts dem Zufall überlassen und ich wollte so nah wie möglich an den inaktiven Brunnen der Ewigkeit kommen wie möglich.\n\nIch sehe schon, dass dies der perfekte Ort ist. Ich kann die Energie in der Luft förmlich spüren. Kommt, lasst uns beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85468] = { id = 85468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seele des Unheils", description = "Wenn ich mir die seltsame Sense anschaue, die Ihr mitgebracht habt, glaube ich, dass wir sie mit Seelen füllen müssen, um sie wiederherzustellen. Fangen wir mit Wichteln an. Ich habe einen Kollegen in den Östlichen Pestländern, in der Nähe von Northdale, der Euch helfen können sollte. Erwähnt meinen Namen, dann sollte er etwas empfänglicher sein. Ich treffe Euch in der Kapelle des hoffnungsvollen Lichts, sobald Ihr fertig seid.", sourceObjective = "Überzeugt Xirath in der Nähe von Northdale in den Östlichen Pestländern, Euch dabei zu helfen, eine Seele des Unheils zu erhalten und sie auf die erschöpfte Sense des Chaos anzuwenden.", completion = "Großartige Arbeit, {name}, die Sense scheint wieder an Kraft zu gewinnen. Oh, Xirath? Eine Schande, dass er uns am Ende hintergangen hat. Dann muss ich wohl einen neuen Kollegen finden. Versuchen wir beim nächsten Mal, die Macht der Seele zu steigern.", sourceObjectiveStatus = "unverified-source-field" }
quests[85480] = { id = 85480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prokrastimunds Dankbarkeit" }
quests[85485] = { id = 85485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seele der Leere", description = "Die Sense kommt schön voran. Die nächste Seele, die Ihr hinzufügen solltet, ist die eines Leerwandlers. Ich kenne da einen, der besonders mächtig ist und der noch verweilt, obwohl sein Meister in der Nähe gestorben ist. Der sollte eine gute Ergänzung sein.", sourceObjective = "Findet den Leerwandler in der Nähe von Corins Kreuzung in den Östlichen Pestländern und fügt seine Seele der Sense hinzu.", completion = "Exzellent, {name}. Seid Ihr für die nächste Phase in der Wiederherstellung der Sense bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[85486] = { id = 85486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seele der Betörung", description = "Eure nächste Aufgabe ist deutlich kniffliger und dreht sich um diese Teufelsportale, die hier immer wieder auftauchen. Ich habe gehört, dass sie mächtige teuflische Eindringlinge beschwören, wenn Magier besondere Schriftrollen einsetzen. Die Geißel im Pestwald scheint etwas Ähnliches vorzuhaben. Verwendet den Dämon, den sie beschwören wollen, auf dieselbe Art für den Seelensplitter.", sourceObjective = "Verwendet eine leuchtende Schriftrolle der räumlichen Heilung an einem großen Teufelsriss, um einen teuflischen Eindringling zu beschwören und seine Seele zu erhalten.", completion = "Ihr habt wirklich alle Erwartungen übertroffen, {name}. Nur noch eine Seele, dann sollte die Sense für ihren finalen Test bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[85501] = { id = 85501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz von Chromaggus", description = "Das Herz des einst furchteinflößenden Chromaggus ruht in Euren Händen. Die kaleidoskopischen Farben sind so exquisit wie grotesk. Ihr spürt eine große Macht im Inneren des Herzens. Etwas, dass sich Eurem Verständnis entzieht. Um mehr zu erfahren, bedarf es der Hilfe von jemandem, der deutlich mächtiger und älter ist als Ihr.", sourceObjective = "Findet jemanden, der die Macht des chromatischen Herzens versteht.", progress = "Was habt Ihr mir da gebracht, Kleine?", completion = "Dieses Herz ist eine schreckliche Anomalität. Wie auch immer, seine Macht könnte möglicherweise reformiert werden, um besseren Zwecken zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85505] = { id = 85505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seele des Verzehrens", description = "Diese Seele sollte interessant sein. Während Ihr weg wart, ist mir zu Ohren gekommen, dass ein streunender Teufelshund einigen Magiern in der Nähe des Blackwoodsees aufgelauert ist. Nehmt diesen besonderen Seelensplitter. Er sollte die Effekte der arkanen Magie verstärken, die auf Euch gewirkt wird. Der Teufelshund wird dem nicht widerstehen können.", sourceObjective = "Findet die Magier in der Nähe des Blackwoodsees und lasst sie Zauber auf Euch wirken, bis der Teufelshund erscheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[85506] = { id = 85506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Prüfung", description = "Ich werde Euch nun meine wahren Absichten offenbaren, {name}. Ich glaube, dass diese Sense dabei helfen kann, Des'Altek ein für alle Mal ein Ende zu setzen. Trefft mich beim Demonfall-Canyon in Ashenvale, dann können wir ihn als die finale Seele nutzen, die wir brauchen, um der Sense wieder ihre volle Macht zu verleihen.", sourceObjective = "Erhaltet die Seele von Des'Altek im Demonfall-Canyon und verwendet sie, um die Wiederherstellung der Sense abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85507] = { id = 85507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser verlorener Freund", description = "Ich bin froh, dass Ihr hier seid, {name}. Uns wurde mitgeteilt, dass in der Nähe des Zugwindlagers ein Reisender gesehen wurde, der auf die Beschreibung Eures Freundes Aeonas passt. Er soll sich in Richtung Trauerhügel begeben haben.\n\nNach allem, was sich im Teufelswald zugetragen hat, wollte ich ihm etwas Freiraum lassen, doch es gibt noch Leute im Orden, die ihm nach wie vor nicht trauen. Und irgendwann muss er aus der Kälte zurückkehren und erklären, warum er seinen anhaltenden Kontakt zu einem bekannten Agenten des Lichkönigs verschwiegen hat. Geht und findet ihn. Vielleicht könnt Ihr ihn ja überzeugen, zurückzukommen.", sourceObjective = "Findet Aeonas in der Nähe von Sorrow Hill in den Westlichen Pestländern.", completion = "Ich hatte das Gefühl, dass Ihr früher oder später auftauchen würdet. Tut mir leid, Euch enttäuschen zu müssen, doch es ist für mich noch nicht an der Zeit, zurückzukehren. Das ist der beste Teil daran, ein \"ehemaliges\" Mitglied der Silbernen Hand zu sein. Ich bin gegenüber niemandem im Orden mehr Rechenschaft schuldig.\n\nAn einem gewissen Punkt werde ich zurückkehren, aber für den Moment könnt Ihr Katharina bitte sagen, dass ich Ihr Gesuch vernommen habe, aber einfach noch nicht bereit bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[85508] = { id = 85508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser verlorener Freund", description = "Ihr seht aus, als wärt ihr richtig stark geworden, seit wir uns das letzte Mal gesehen haben. Das freut mich wirklich. Wenn es etwas gibt, dass ich in meinem Leben richtig gemacht habe, dann, Euch im Teufelswald das Leben zu retten. Und das gibt mir Trost.\n\nEgal, Ihr solltet jetzt besser wieder zu Katharina zurückkehren, oder gibt es noch etwas anderes, das Ihr mich fragen wolltet?", sourceObjective = "Sprecht mit Aeonas, bevor Ihr nach Stormwind zurückkehrt, um Katharina seine Antwort zu übermitteln.", completion = "{name}, dem Licht sei Dank, dass Ihr hier seid! Die Kammer wurde gerade überfallen und die Echokugel der Mannoroc entwendet!", sourceObjectiveStatus = "unverified-source-field" }
quests[85509] = { id = 85509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sondereinsatz Echokugel", description = "Begebt Euch bitte zum südöstlichen Bereich des Kanals und sprecht mit dem dortigen Kammerhüter, Julien Faranister. Er kann Euch erzählen, was er weiß. Bringt über das Verbrechen so viel wie möglich in Erfahrung. Es gibt viele Leute, die an der Kugel Interesse haben, daher ist es umso wichtiger, jetzt so viele Indizien wie möglich zu sammeln, solange der Tatort noch frisch ist.", sourceObjective = "Sprecht mit Faranister dem Kammerhüter im Kanaldistrikt von Stormwind und kehrt anschließend zu Katharina zurück, sobald Ihr so viel wie möglich in Erfahrung gebracht habt.", progress = "Warum sprecht Ihr mit mir, {name}! Geht so schnell wie möglich zum Kammerhüter.", completion = "Das ist nicht gerade viel, aber immer noch besser als nichts, schätze ich.\n\nIch würde gerne hören, was Ihr während Eures Treffens mit Aeonas in Erfahrung bringen konnten, aber ich fürchte, dass dieses Anliegen gerade Priorität hat. Sprechen wir über unseren aktuellen Anhaltspunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85510] = { id = 85510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine mögliche Spur", description = "Das ist zweifelsohne ein Medaillon der Brennenden Klinge, was auf eine Beteiligung des Kults der Legion hindeutet. Was den Start Eurer Untersuchung betrifft... vielleicht solltet Ihr den Tavernen in der Stadt einen Besuch abstatten und versuchen, den verruchteren Gästen einige Informationen zu entlocken. \n\nEs ist nicht viel, aber einen Anfang ist es wert.", sourceObjective = "Erkundet einige der weniger ruhmreichen Teile Stormwinds und sucht dort nach Informationen dazu, wer möglicherweise geplant hatte, die Kammer auszurauben.", completion = "Ihr seht wie jemand aus, der gerade etwas verloren hat...\n\nIch hatte bereits vermutet, dass Ihr hier früher oder später auftauchen würdet, um danach zu suchen. Ihr habt es schneller hergeschafft, als ich vermutet hätte. Hut ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[85511] = { id = 85511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pestlandtreffen", description = "Natürlich habe ich damit gerechnet, dass Ihr mich hier findet. Was dachtet Ihr denn, weshalb ich Euch all die Kultistenleichen in der Kammer hinterlassen habe?\n\nBevor Ihr Euch zu sehr aufregt: Ja, die Kugel ist sicher. Allem Anschein nach sogar sicherer als diese Stadt. Wäre ich nur etwas später in die Kammer gekommen, wäre die Kugel bereits längst weg gewesen.\n\nIch habe bereits genug gesagt und diese Taverne hat zu viele Ohren. Trefft mich auf der Insel Caer Darrow in den Westlichen Pestländern. Dort sollt Ihr Eure Antworten bekommen.", sourceObjective = "Sucht Ada Dunkelhardt in Caer Darrow in den Westlichen Pestländern.", completion = "Ich kann spüren, dass das Ende bevorsteht. Hoffentlich können wir einen angemessenen Ersatz für Euer Blut finden und diese Angelegenheit ein für alle Mal hinter uns lassen.\n\nSo oder so, Ihr habt den langen Weg auf Euch genommen und nicht versucht, mich umzubringen. Das weiß ich wirklich zu schätzen. Hier, nehmt das hier als Zeichen meiner Dankbarkeit an. Es ist nicht viel, aber es hat mir gute Dienste erwiesen... in einem anderen Leben zumindest. Hoffentlich kann es auch Euch eine Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[85521] = { id = 85521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Fallensteller auf der Spur", description = "Die Notiz, die Ihr gefunden habt, scheint ein Beleg für die Unterdrückungsfallen zu sein, die sich um das Lager von Brutwächter Dreschbringer befinden. Die Notiz beschreibt, dass wenn der Brutwächter mehr Unterdrückungsfallen braucht, er sie vom Lager des Verkäufers kaufen kann, das sich in der Nähe der westlichen Seite der Brennende Steppe südlich der Straße zum Altar der Stürme befindet. In der Notiz steht auch, dass der Verkäufer bald weiterzieht, weshalb der Brutwächter sich beeilen sollte, wenn er mehr Fallen braucht.", sourceObjective = "Findet das verlassene Lager an der westlichen Seite der Brennenden Steppe, südlich der Straße zum Altar der Stürme, und untersucht das Gebiet.", progress = "Das verlassene Lager sollte einige Hinweise bieten.", completion = "Vielleicht können wir zusammenarbeiten. Ich gehe gerade noch ein paar anderen Spuren nach, doch wir können unsere Aufzeichnungen miteinander teilen, um diesen Verbrecher gegen die Natur aufzuhalten, bevor er noch mehr Schaden verursacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[85525] = { id = 85525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nacht in Winterspring", description = "Ein Zelt allein wird nicht genug sein, um eine stürmische Nacht in Winterspring zu überleben. Ihr braucht Essen, Felle und Feuer, um Euch warm zu halten, sonst friert Ihr noch zu Tode. Glücklicherweise bietet Euch die Natur alles, was Ihr braucht, und Ihr könnt das alles hier finden.", sourceObjective = "Sammelt Bärenfleisch, warmes Fell und trockenes Holz. Bringt die Materialen zu Eurem Lager, um einen Unterschlupft zu bauen, damit Ihr den Sturm überstehen könnt.\n\nWenn Ihr das Fundament verliert, errichtet Ihr mit Euren Überlebensvorräten ein neues und bringt die Materialien dorthin.", sourceObjectiveStatus = "unverified-source-field" }
quests[85555] = { id = 85555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwermetall", description = "Die große flache Scheibe aus Elementium, die Ihr in den Händen haltet, scheint vor elementarer Energie zu brummen. Ihr könnt schon fast hören, wie die Elementargeister Euch etwas zuflüstern. Ihr seid nicht sicher, was Ihr damit anstellen sollt, aber die Verbindung, die Ihr spürt, ist unmittelbar vorhanden.\n\nWenn sich ein ausreichend talentierter Schmied, der sich mit diesem mysteriösen, als Elementium bekannten Metall auskennt, ein wenig damit beschäftigt, könnte eine Waffe oder ein Rüstungsteil daraus entstehen. Das vermutet Ihr zumindest.", sourceObjective = "Findet jemanden, der exotische Metalle verarbeiten kann und bereit ist, Euch zu helfen, etwas Besonderes aus diesem Elementiumklumpen herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85556] = { id = 85556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Sammlung an Fertigkeiten", description = "Krixix ist sicherlich ein Genie, aber möglicherweise ist er nicht allzu freundlich gestimmt, wenn Ihr einfach in den Berg stürmt und nach seiner Hilfe verlangt. Ganz zu schweigen von den Schlägern, von denen es da vermutlich wimmelt. Ihr solltet versuchen, einen Weg zu finden, wie Ihr zu ihm gelangt, ohne alles unterwegs abzufackeln, was wahrscheinlich ziemlich knifflig werden könnte.\n\nWenn Ihr einen Weg da rein finden könnt, ohne unterwegs Leute zu erstechen, zu verbrennen oder sonst wie zu erledigen, ist das wahrscheinlich schon ein guter Anfang. Ich selbst habe keine gute Idee, wie das funktionieren soll, also viel Glück dabei!", sourceObjective = "Findet einen Weg, um in den Pechschwingenhort zu gelangen und mit Meisterelementarformer Krixix zu sprechen, ohne ihn in einen Kampf zu verwickeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[85557] = { id = 85557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effizienz hat oberste Priorität", description = "Tatsächlich ist mir da gerade eine Idee gekommen. Seht mal, das größte Problem bei der Verarbeitung von Elementium besteht darin, die Schmiede heiß genug zu halten. Wenn ich etwas hätte, womit ich das Feuer länger bei voller Stärke halten könnte, müsste ich nicht so viel Zeit damit verschwenden, es zu schüren.\n\nWenn Ihr mir ein magisches Mittelchen bringt, das meine Schmiede heiß hält, könnte ich mich ein wenig für etwas nebenher freimachen, wie für Euren kleinen Auftrag. Jetzt verschwindet. Seht zu, was Ihr für mich auftreiben könnt.", sourceObjective = "Findet eine geeignete Energiequelle, um die Elementiumschmiede von Meisterelementarformer Krixix effizienter zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85558] = { id = 85558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Qualität ist eine Verpflichtung", description = "Ich habe darüber nachgedacht, was wir mit diesem Klumpen Metall anfangen sollen, und ich glaube, ich habe genau die richtige Idee. Gebt mir ein paar Minuten, dann dengel ich das für Euch zusammen.", sourceObjective = "Seht zu, wie Meisterelementarformer Krixix Euren Gegenstand herstellt.", completion = "Da ist sie. Ist sie nicht eine Schönheit? Lasst Euch nicht davon täuschen, wie lange ich gebraucht habe, das hier zusammenzuhauen. Ich lasse es nur einfach aussehen. Ich versichere Euch, das ist ein Meisterstück.\n\nIch denke sogar, dass dies meine beste Arbeit sein könnte. Natürlich ist alles, was ich mache, meine beste Arbeit. Nun, was für eine lustige kleine Ablenkung, aber jetzt muss ich wieder an die Arbeit. Wir sehen uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[85559] = { id = 85559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbruch der Nacht", description = "Wenn Ihr mich bitte begleitet? Ich muss Euch noch eine letzte Sache zeigen.", sourceObjective = "Begleitet Estelenn und seht Euch an, was sie Euch zeigen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[85595] = { id = 85595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Präsenz der Macht", progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, {class}. Zeigt keine Gnade mit den Hakkari!" }
quests[85596] = { id = 85596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umarmung des Todes", progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, {class}. Zeigt keine Gnade mit den Hakkari!" }
