quests[85973] = { id = 85973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen", progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass Ihr beträchtliches Ansehen bei meinen Truppen, den hydraxianischen Wasserlords, erhaltet. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegenbringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, {name}, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen." }
