quests[85982] = { id = 85982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen" }
quests[85983] = { id = 85983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen", progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf beim Stamm der Zandalari ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf würde sich stark verbessern.\n\nSo oder so, ich nehme eure Abzeichen nur zu gerne an.", completion = "Also gut, Eure Taten haben bei den Zandalari Anerkennung gefunden. Immer weiter so, {class}.\n\nWenn Ihr weitere Abzeichen abgeben möchtet, dann immer her damit." }
quests[85984] = { id = 85984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen", progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf beim Stamm der Zandalari ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf würde sich stark verbessern.\n\nSo oder so, ich nehme eure Abzeichen nur zu gerne an.", completion = "Also gut, Eure Taten haben bei den Zandalari Anerkennung gefunden. Immer weiter so, {class}.\n\nWenn Ihr weitere Abzeichen abgeben möchtet, dann immer her damit." }
quests[85985] = { id = 85985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen", progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Stamm der Zandalari sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Ausgezeichnet! Ihr habt Opfer gebracht, um diese Abzeichen zu verdienen, und dafür sollt Ihr auch entsprechend Anerkennung finden. Abenteurer wie Ihr, {name}, machen einen wahren Unterschied.\n\nKommt zu mir, wenn Ihr weitere Abzeichen abgeben möchtet, ich helfe Euch gerne dabei, sie einzutauschen." }
quests[85986] = { id = 85986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen", progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Stamm der Zandalari sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Ausgezeichnet! Ihr habt Opfer gebracht, um diese Abzeichen zu verdienen, und dafür sollt Ihr auch entsprechend Anerkennung finden. Abenteurer wie Ihr, {name}, machen einen wahren Unterschied.\n\nKommt zu mir, wenn Ihr weitere Abzeichen abgeben möchtet, ich helfe Euch gerne dabei, sie einzutauschen." }
quests[85987] = { id = 85987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen" }
quests[85988] = { id = 85988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen" }
quests[86160] = { id = 86160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen", progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Außenseiter im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass Ihr beträchtliches Ansehen bei der Holzschlundfeste erhaltet. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf nur geringfügig verbessern.\n\nGenug geredet! Ich würde nur zu gerne Eure Abzeichen entgegennehmen.", completion = "Ausgezeichnet! Ihr habt Opfer gebracht, um diese Abzeichen zu verdienen, und dafür sollt Ihr auch entsprechend Anerkennung finden. Außenseiter wie Ihr, {name}, können einen echten Unterschied machen.\n\nKommt zu mir, wenn Ihr weitere Abzeichen abgeben möchtet, ich tausche sie gerne gegen mehr Ansehen ein." }
quests[86161] = { id = 86161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen" }
quests[86326] = { id = 86326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenmacht", description = "Die tiefen und finsteren Tunnel zu den uralten Orten der Welt eignen sich nur schlecht für Eure Reise.", sourceObjective = "Sprecht mit Selestrasza, um Euren Qirajiresonanzkristall zu erhalten.", completion = "Eure Macht ist nicht unbemerkt geblieben, sterbliches Wesen. Nutzt diesen gezähmte Silithiden, um Eure Reise in das uralte Reich der Qiraji zu beschleunigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86442] = { id = 86442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nefarians Verderbnis", description = "Held, seid Ihr es? Es ist tausend Jahre her, seitdem man mir den Splitter anvertraut hat. Jetzt, in meiner finstersten Stunde soll jemand erscheinen, um ihn mir zu nehmen... aber was wäre eine Tragödie ohne Grausamkeit?\n\n<Vaelastrasz hustet geschwächt.>\n\nNe... Nefarian besitzt nun den Szeptersplitter.\n\nDie Zeit ist knapp. Nefarian hat vor, den Splitter zu zerstören. Ihr müsst Euch beeilen!", sourceObjective = "Tötet Nefarian und bringt den roten Szeptersplitter wieder in Euren Besitz. Bringt den roten Szeptersplitter zu Anachronos in den Höhlen der Zeit in Tanaris. Euch bleiben 5 Stunden, um diese Aufgabe zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86443] = { id = 86443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alptraum offenbart sich", description = "Wir müssen gegen Eranikus mit Bedacht vorgehen. Wir sollen ihn erlösen, nicht vernichten.\n\nTyrande ist bereits auf dem Weg, um uns bei dieser Aufgabe zu unterstützen. Wir müssen die Attacken des Drachen überstehen und Nighthaven vor der sicheren Zerstörung bewahren.\n\nSeid auf der Hut! Ihr und Eure Verbündeten seid unsere einzige Hoffnung.", sourceObjective = "Verteidigt Nighthaven gegen Eranikus. Bewahrer Remulos darf dabei nicht ums Leben kommen und Eranikus darf nicht getötet werden. Verteidigt Euch. Erwartet Tyrande.", completion = "Er ist erlöst, {name}. Jetzt kehrt er in den Traum zurück, um zu richten, was er alleine zerstört hat. Eranikus wird ein mächtiger Verbündeter Malfurions und meines Vaters sein.\n\nDiese Rüstungsteile sind für Euch, {name}; Ysera selbst hat sie mir gegeben. Ihr würdet gut daran tun, wenn Ihr sie bei Euren Kämpfen gegen die Qiraji einsetzen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[86444] = { id = 86444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einzige Weg", description = "Ich hätte es wissen müssen. Mein Erzfeind, Doktor Weavil, hat wieder seine dreckigen Finger im Spiel! Jetzt, nach Eurem Versagen in Winterspring, hat Doktor Weavil mein Buch zerstört! Wie wollt Ihr jetzt die Welt retten?\n\nDie Nachricht, die ich erhalten habe, gab an, dass die einzig bekannte Kopie von \"Drachisch für Dummies: Band 2\" in 8 Teile zerrissen und im Wind zerstreut wurde! Solltet Ihr diese fehlenden Kapitel irgendwie finden können, dann verwendet diesen magischen Bucheinband, um sie wieder zusammenzuflicken. Kehrt dann zu mir zurück.", sourceObjective = "Findet die 8 verlorenen Kapitel von \"Drachisch für Dummies\" und vereint sie mit dem magischen Bucheinband. Bringt das vollständige Buch \"Drachisch für Dummies: Band 2\" dann zu Narain Soothfancy in Tanaris.", progress = "Ich mach's genauso wie Ihr - und wenn, dann mache ich es richtig... und sollte es sich anbieten, dann mache ich Arkanitbojen. Arkanitbojen, Baby!", completion = "Fantastisch! Ich kann nicht glauben, dass Ihr Euch diese Mühe gemacht habt! Seid Ihr so eine Art Maschine? Wenn es nach mir ginge, hätte ich die Welt wahrscheinlich ganz einfach implodieren lassen.\n\nIch ziehe meinen Turban vor Euch, holde Dame. Keine gute Tat soll unbezahlt bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[86445] = { id = 86445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn von Neptulon", description = "Hatte ich die schlechte Neuigkeit schon zur Sprache gebracht? Sein Name ist \"Der weiße Riese\": Einhundert Meter Tod und Zerstörung pur. Den kleinen Leckerbissen hatte ich glatt vergessen.\n\nMeinen gnomischen Superpsychokräften nach zu urteilen, befindet sich der beste Ort, um diese Boje zu platzieren, an der Küste Azsharas in der Bucht der Stürme.\n\nHaltet nach einem wirbelnden Strudel Ausschau. Vermutlich ist die ganze Gegend mit Wrackteilen übersät.\n\nMacht es gut und nehmt ein paar Freunde mit.\n\nFalls Ihr die ganze Sache wie durch ein Wunder überleben solltet, bringt den Szeptersplitter zu Anachronos.", sourceObjective = "Benutzt die Arkanitboje am wirbelnden Maelstrom in der Bucht der Stürme in Azshara.", progress = "Die Zeit läuft uns davon, große Heldin!", completion = "Gut gemacht, {name}. Schon bald werde ich das Szepter der Sandstürme wieder zusammensetzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[86449] = { id = 86449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz des Zeitlosen", sourceObjective = "Seid gegrüßt, große Heldin! Ich bin Jonathan, der Bewahrer des heiligen Gongs und ewige Wächter des bronzenen Drachenschwarms.\n\nDer Zeitlose hat mich dazu ermächtigt, Euch aus seinem Schatz einen Gegenstand Eurer Wahl zu gewähren. Möge er Euren Kampf gegen C'Thun erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[86670] = { id = 86670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Retter von Kalimdor", description = "Begebt Euch zu den Höhlen der Zeit, <Lord/Lady> {name}. Anachronos erwartet Eure Rückkehr. Übergebt ihm das Auge von C'Thun. Sicherlich wird er es der Sammlung seines Meisters hinzufügen wollen.", sourceObjective = "Bringt das Auge von C'Thun zu Anachronos in den Höhlen der Zeit.", progress = "Lord {name}! Es ist vollbracht...", completion = "Der Meister hat dies für Euch zurückgelassen, großer Held. Aus dem zeitlosen Schatz: Eine Sammlung verschiedenster Artefakte, über Tausende von Jahren zusammengetragen. Ihr habt die Wahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[86671] = { id = 86671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Qirajiinsignien", description = "Arygos hat die Theorie aufgestellt, dass das Element, welches während des Konflikts zwischen den Alten Göttern und ihren Anhängern entstanden ist, unter den richtigen Bedingungen für sie tödlich ist. Ich spreche vom Elementium, <Sterblicher/Sterbliche>.\n\nFindet und bringt mir imperiale Qirajiinsignien sowie das giftige Element, dann werde ich Euch Waffen von größter Macht erschaffen!", sourceObjective = "Merithra des Traums im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen. Bringt ihr dazu imperiale Qirajiinsignien und 3 Einheiten Elementiumerz.", sourceObjectiveStatus = "unverified-source-field" }
quests[86672] = { id = 86672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Qirajiwaffen", description = "Wir haben hier nicht ein Jahrtausend in völliger Untätigkeit verbracht, {name}.\n\nWir sahen mit eigenen Augen, wie sich diese Biester an ihren eigenen Artgenossen gütlich taten, nachdem diese ihre Nützlichkeit für den Schwarm verloren hatten. Wir lauschten, als sie ihre Pläne schmiedeten, diese Welt in Schutt und Asche zu legen. Und wir lernten, wie sich Verrat und Missgunst in ihren Reihen ausbreiten.\n\nSie haben Schwächen und wir wissen nun, wie wir diese zu unserem Vorteil nutzen können.\n\nFindet und bringt mir ihre Zeremonienwaffen. Zusammen mit dem durch ihren Gott erschaffenen Element werden wir daraus mächtige Instrumente der Zerstörung erschaffen.", sourceObjective = "Arygos im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen, wenn Ihr ihm imperiale Qirajiwaffen und 3 Einheiten Elementiumerz bringt.", progress = "Findet, worum ich Euch gebeten habe, und Ihr werdet weit mehr als nur die Summe Eurer Teile werden, großer Held.", completion = "Jetzt, da diese Waffen mit Elementium erfüllt sind, werden sie sich mit Leichtigkeit durch jeden Qiraji und ihren Gott schneiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[86673] = { id = 86673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang von Ossirian", description = "Eine schreckliche Bedrohung hat ihr Ende gefunden. Der grausame Ossirian existiert nicht mehr.\n\nDie Bewohner Kalimdors werden aufatmen, wenn sie von diesem glorreichen Sieg erfahren. Nehmt Ossirians Kopf und bringt ihn zu Kommandant Mar'alith auf Burg Cenarius.", sourceObjective = "Bringt den Kopf von Ossirian dem Narbenlosen zu Kommandant Mar'alith auf Burg Cenarius in Silithus.", progress = "Ah, {name}. Wie ich sehe, seid Ihr zurückgekehrt und sogar in einem Stück! Welche Neuigkeiten bringt Ihr aus Ahn'Qiraj?", completion = "Ich entbiete Euch meine höchste Anerkennung und erlaube es Euch, einen Gegenstand von höchster Macht auszuwählen, {name}! Ihr habt den Bewohnern von Kalimdor einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86674] = { id = 86674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Gift", description = "Mein Bruder und ich sind im Ravenholdt-Anwesen für den Giftbedarf zuständig.\n\nLord Ravenholdt hat mich damit beauftragt, eine neue und extrem effektive Giftmischung zusammenzustellen, die aus den Giftbeuteln der Bewohner von Zul'Gurub und den Ruinen von Ahn'Qiraj gewonnen werden kann.\n\nEs gibt in diesen verfluchten Ruinen zwei ganz besonders giftige Bestien, die vielleicht genau das haben, wonach wir suchen, {class}. Bringt mir einen Giftbeutel der Bestien Kurinnaxx und Venoxis und wir wären Euch ewig dankbar.", sourceObjective = "Dirk Thunderwood in der Burg Cenarius will, dass Ihr ihm Venoxis' Giftbeutel und Kurinnaxx' Giftbeutel bringt.", progress = "Alleine packt Ihr das nicht, {name}. Ihr werdet Kameraden mitbringen müssen.", completion = "Ravenholdt dankt Euch, Held! Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[86675] = { id = 86675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Kriegsfreiwilligen", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, {name}.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", sourceObjective = "Bringt 5 cenarische Gefechtsabzeichen, 3 cenarische Versorgungsabzeichen und 7 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[86676] = { id = 86676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Veteranen", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, {name}.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", sourceObjective = "Bringt 7 cenarische Gefechtsabzeichen, 4 cenarische Versorgungsabzeichen und 4 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[86677] = { id = 86677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Gefolgsmanns", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Windruferin Proudhorn erhalten habt, dienen zu weit mehr als der Angeberei, {name}.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", sourceObjective = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 17 cenarische Strategieabzeichen und 1 Mal von Remulos zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[86678] = { id = 86678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Feldherren", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, {name}.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", sourceObjective = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 20 cenarische Strategieabzeichen und 1 Mal des Cenarius zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[86679] = { id = 86679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingehüllt in Alpträume", description = "Verderbtheit umgibt dieses Objekt.\n\nVielleicht gibt es eine Verbindung zwischen diesem Gegenstand und den aus dem Traum vordringenden Drachen. Sucht nach jemandem, der die Bedeutung dieses Gegenstands entschlüsseln kann. Vielleicht können Euch die Druiden aus Moonglade oder auf Burg Cenarius weiterhelfen.", sourceObjective = "Sucht nach jemandem, der die Bedeutung des in Alpträume gehüllten Gegenstands entschlüsseln kann.\n\nVielleicht kann Euch ein Druide von großer Macht weiterhelfen.", progress = "Ja, {race}?", completion = "Ich muss diesen Gegenstand zuerst von seiner Verderbnis reinigen. Möglicherweise gibt er mir Aufschluss darüber, warum es mir zuletzt unmöglich war, in den Smaragdgrünen Traum einzutauchen. Bitte, gebt ihn mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[86680] = { id = 86680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legenden erwachen", description = "Das Wasser des Elune'ara Sees wird die Alpträume auflösen, die den Gegenstand umgeben. Bitte, gebt mir einen Moment, um die Reinigung durchzuführen, {name}.", sourceObjective = "Wartet, bis Bewahrer Remulos in Moonglade den von Alpträumen eingehüllten Gegenstand gereinigt hat.", progress = "Ihr habt gesehen, was Ihr sehen müsst!", completion = "Nehmt diesen Ring, {name}. Er hat seinen Zweck für Malfurion erfüllt. Er soll nun Euch dienen...", sourceObjectiveStatus = "unverified-source-field" }
quests[86724] = { id = 86724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staub zu Staub", description = "Leiht mir Euer Ohr, {name}. Die Wunden des Captains werden immer schwerer. Das Lager feiert jeden Sieg mit dem üblichen Jubel, doch ich kann mich dieser Freude nicht anschließen. Nicht, wenn ich die Wunden sehe, die er unter seiner Rüstung verbirgt.\n\nEine Infektion? Nein, ich würde sagen, dass viel eher einer... einer Infestation gleicht. Ich arbeite an einer Zubereitung, doch eine letzte, aber wichtige Zutat fehlt mir: Silithyst.\n\nIch brauche es. Und zwar schnell. Wenn ich mir den Zustand des Captains so ansehe, fürchte ich, dass er ohne ein Heilmittel nicht mehr lange durchhält.", sourceObjective = "Findet 5 Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Apotheker Quinard beim Lager der Horde in der Nähe des Regalschwarmbaus.", completion = "Exzellent. Ihr habt alles gefunden. Und zwar gerade noch rechtzeitig. Ich werde mich sofort daran setzen, das Mittel für Captain Krug zuzubereiten.\n\nIch kann Euren Wagemut leider nicht mit Münzen belohnen, doch ich kann Euch an meinem Wissen teilhaben lassen. Ich bin gewillt, Euch gegen einen kleinen Preis die Notizen zu überlassen, mit deren Hilfe ich die Soldaten verarztet und ihre Bäuche gefüllt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[86725] = { id = 86725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staub zu Staub", description = "Ach ja, die Gefahren der Wüste. Nein, nicht die Bullenhitze, nicht die gnadenlosen Sonnenstrahlen, nicht der Sand, der in alle Ritzen und Falten Eurer Roben kriecht, nicht die klirrend kalten Nächte.\n\nDie anderen Gefahren! Die Käfer und jetzt noch diese lästigen Grobiane. Unsere Aufklärungstrupps berichten, dass die Horde Dreck sammelt.\n\nNormalerweise wäre das nichts Besonderes für sie, aber Silithyst? Es wäre mir lieber, wenn sie die Geheimnisse des Sandes nicht ergründen. Als Chefexpeditionslieferant beantrage ich eine konkurrierende Lieferung! Besorgt mir diesen Dreck!", sourceObjective = "Findet 5 Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Chefexpeditionslieferant Enkles beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", progress = "Was macht Ihr hier noch, {name}? Mein Voraussichtsstrank hat mir gezeigt, dass Ihr die Person für diesen Auftrag seid!\n\nWir haben es geschafft, die Essenz der Silithuskristalle in einen Trank zu destillieren, der dem Anwender für kurze Zeit die Fähigkeit der Voraussicht verleiht.\n\nAch, entschuldigt bitte, doch ich habe noch nicht die Befugnis, Euch diese Tränke zur Verfügung zu stellen.", completion = "Sehr gut, {name}! Erlaubt mir kurz, diese Transaktion in meinen Büchern festzuhalten...\n\nUnd das wäre es. Falls wir andere Lieferprobleme haben, werde ich sie an Euch weiterleiten. Und als Chefexpeditionslieferant erwarte ich Unterstützung.\n\nIch habe leider nicht die Befugnis, Euch zu bezahlen, doch ich habe mir diese Position nicht verdient, indem ich meine Untergebenen nicht anständig entlohne! In meinem Besitz befinden sich viele Rezepte, die angefordert, aber nie ausgeliefert wurden. Als Belohnung genehmige ich Euch, Exemplare aus meinem Bestand an Lektüren mit verlorenem Wissen käuflich zu erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[86760] = { id = 86760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestienkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Bestienkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Bestienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[86761] = { id = 86761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherrenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Kriegsherrenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Kriegsherrenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[86762] = { id = 86762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Elementarkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Elementarkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[86763] = { id = 86763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portalkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Portalkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Portalkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[86964] = { id = 86964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Gold und Ehre!", description = "An alle Abenteurer und Schatzsucher! Hiermit wird bekannt gegeben, dass die Kirin Tor die Auszahlung beträchtlicher Gelder an all jene genehmigt hat, die imstande sind, in die Gruften unter Karazhan hinabzusteigen und ein bestimmtes magisches Artefakt zu bergen. Alle anderen geborgenen Schätze, Kuriositäten oder Münzen haben für den Orden keine Bedeutung und können als zusätzliche Entschädigung behalten werden. Interessenten melden sich bitte bei... \n\n<Der untere Teil dieser Notiz wurde abgerissen und die restlichen Details fehlen.>", sourceObjective = "Offenbar sucht jemand nach Abenteurern, die etwas Wertvolles aus den Karazhangruften am Gebirgspass der Totenwinde bergen können. Es ist nicht bekannt, wer diesen Aushang gemacht hat oder wo man die Auftraggeber finden kann, aber die Aussicht auf eine beträchtliche Belohnung von einer angesehenen und finanzstarken Gruppe wie den Kirin Tor sowie auf einen Schatz, der nur darauf wartet, geborgen zu werden, ist zugegebenermaßen sehr reizvoll.\n\nReist zum Gebirgspass der Totenwinde und untersucht die Gruften hinter dem Karazhan-Turm.", completion = "Diese vor Euch liegende Person ist tatsächlich ziemlich tot. Sie scheint keine offensichtlichen Wunden oder andere Verletzungen aufzuweisen. Das einzig Auffällige an der Leiche ist der Ausdruck höchster Furcht in ihrem Gesicht. Fast so, als wäre diese Frau vor Schreck gestorben...", sourceObjectiveStatus = "unverified-source-field" }
quests[86965] = { id = 86965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine natürlichen Schatten", description = "Eine plötzliche und beklemmende Dunkelheit legt sich über Euch, als ihr Euch hinkniet. Ihr bemerkt, dass alles Licht in der Nähe dunkler und schwächer zu werden scheint, als würde die Dunkelheit nach Euch greifen. Dies sind keine natürlichen Schatten. \n\nEin kurzer Blick zum Eingang der nahe gelegenen Gruft genügt, um zu erkennen, dass diese bösartige Dunkelheit von der Gruft selbst ausgeht und sie mit ihren tintenschwarzen Ranken nach mehr Licht sucht, das sie auslöschen kann. Ihr erschaudert, und Euch stellen sich die Nackenhaare auf.", sourceObjective = "Die vom Eingang der Gruft eindringende Finsternis scheint sich allen Gesetzen von Logik und Vernunft zu entziehen. Keinerlei Licht dringt ein oder kann diese Finsternis vertreiben, und kein Licht im Inneren scheint ihr entkommen zu können. Ihr habt den dringenden Verdacht, dass Euer eigentlich geplantes Betreten der Gruft auf direktem Wege Euer Ende sein könnte.\n\nIhr müsst einen Weg finden, diese Dunkelheit zu überwinden, wenn Ihr vorankommen wollt. Ihr erinnert Euch, dass sich in einem Lager im Norden eine Agentin von Dalaran befindet. Vielleicht weiß sie mehr über den toten Abenteurer und diese merkwürdige Dunkelheit?", completion = "<Agentin Keanna schaut zu Euch auf und runzelt etwas die Stirn.>\n\nSchaut, ich habe der letzten Gruppe, die hierher kam, schon gesagt, dass ich keine Informationen über die Gruften habe. Und das gleiche gilt für die Belohnung, die mein Orden auf den verfluchten Schatz ausgesetzt hat, der unter dem alten Turm liegt. Diese Angelegenheiten liegen nicht in meinem Fachgebiet, und ich bin nicht befugt, im Namen des Ordens größere Ausgaben zu leisten.\n\nWenn es sonst nichts gibt, würde ich gerne zu meiner Forschung zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[86966] = { id = 86966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überlebenden suchen", description = "Oh, ich verstehe. Ja, die Leiche, die Ihr gefunden haben wollt, scheint tatsächlich meiner Erinnerung einer der Abenteurer zu entsprechen, die vor Kurzem hier vorbeigekommen sind. Soweit ich mich erinnere, waren sie zu fünft. Ich habe ihnen dringend davon abgeraten, noch weiter zu gehen, aber sie ließen sich nicht davon abbringen. Offenbar waren meine Warnungen begründet, denn seitdem habe ich keinen von ihnen mehr gesehen. Ich befürchtete das Schlimmste und, nun ja...\n\nIhr sagt, sie war die einzige Leiche, die Ihr gefunden habt? Wenn das wahr ist, gibt es vielleicht doch noch andere Überlebende irgendwo auf dem Pass?", sourceObjective = "Sucht nach eventuellen Überlebenden der unseligen Abenteurergruppe und versucht, so viel wie möglich über die Geschehnisse in der Gruft herauszufinden.", completion = "Der Mann rührt sich leicht, als Ihr Euch nähert. Er öffnet fast unmerklich ein einzelnes Augenlid, um Euch anzusehen. Zunächst schien er schwer verletzt zu sein, aber jetzt seid Ihr Euch nicht mehr ganz sicher...", sourceObjectiveStatus = "unverified-source-field" }
quests[86967] = { id = 86967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Hilfe", description = "<Das geöffnete Auge des Mannes sieht Euch direkt an.>\n\nPst, hey Ihr. Ja, Ihr! Glaubt Ihr, Ihr könnt mich hier rausholen? Ich liege hier schon seit Stunden herum und stelle mich tot. Aber es ist nur eine Frage der Zeit, bis diese verdammten Oger sich daran erinnern, dass ich hier bin, und dann kommen, um mich aufzufressen oder mir noch Schlimmeres anzutun!\n\nDieser Käfig ist ziemlich gut verriegelt, aber einer dieser Grobiane müsste einen Schlüssel haben. Seht doch mal nach, ob Ihr einen finden könnt, und lasst mich dann raus. Ich würde dann auf jeden Fall in Eurer Schuld stehen.\n\nIch werde mich weiter tot stellen, während Ihr Euch an die Arbeit macht. Und jetzt geht... Aber leise!", sourceObjective = "Findet den Schlüssel zum Käfig in der Höhle der Totenwindoger und befreit den verletzten Abenteurer darin.", completion = "Wie um Azeroths willen bin ich, blutend und mit einer Gehirnerschütterung, vor Euch hier angekommen?\n\n<Harrison Jones schüttelt den Kopf.>\n\nSeid Ihr sicher, dass Ihr dem gewachsen seid?", sourceObjectiveStatus = "unverified-source-field" }
quests[86968] = { id = 86968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angst vor der Dunkelheit?", description = "Ich kann Euch wirklich nicht genug für Eure Hilfe danken. Ihr habt mir wirklich den Allerwertesten gerettet.\n\nIch habe mich mit dieser netten jungen Dame unterhalten, während ich auf Euch gewartet habe. Und ich glaube, sie weiß vielleicht, wie Ihr in diese trostlose Gruft gelangen könnt, wenn Ihr unbedingt Euer Glück herausfordern wollt.\n\nAber ich greife gerade etwas vor. Ich glaube, ich schulde Euch zunächst noch ein paar Informationen.", sourceObjective = "Hört Harrison Jones zu, während er Euch erzählt, was sich in den Karazhangruften zugetragen hat.", completion = "Offenbar ist es Jones' Gruppe also gelungen, in die Gruft einzudringen und dort einen beträchtlichen Schatz zu finden. Die Dunkelheit, die Ihr beide beschrieben habt, scheint tatsächlich magischer Natur zu sein. Ganz offensichtlich haben ihre stümperhaften Plünderungsaktivitäten etwas Bösartiges zum Leben erweckt.\n\nIch habe in meinem Zauberfolianten nachgeschlagen und glaube, dass ich Euch vielleicht einen Weg durch die Dunkelheit zeigen kann, falls Ihr Euch immer noch mutig genug fühlt, weiterzumachen. Kommt, lasst uns diese Angelegenheit näher besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86969] = { id = 86969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hypothese", description = "Ich denke, ich kann eine Art magisches Totem herstellen, mit dem Ihr diese bösartige Dunkelheit durchdringen und zumindest die Gruften erkunden könnt. Ich habe jedoch nicht alle Komponenten zur Hand. Einige davon sind vielleicht schwer zu finden, aber nach dem, was ich bisher von Euch gesehen habe, vertraue ich darauf, dass Ihr findig genug seid, das Benötigte zu beschaffen.", sourceObjective = "Seht Euch die Liste der benötigten Materialien an und bringt Agentin Keanna die erforderlichen Komponenten.", progress = "Habt Ihr die benötigten Komponenten finden können?", completion = "Ausgezeichnet. Diese Bindung ist ziemlich simpel, ich muss nur kurz... So! Ich denke, das sollte gehen.\n\nDiese magische Fackel sollte es Euch ermöglichen, die bösartige Dunkelheit zu durchdringen, um zumindest die Gruft zu sehen und zu erkunden. Seid jedoch gewarnt, denn das Irrlicht, das diesem Gegenstand innewohnt, hat seinen eigenen Willen. Ich habe es zwar an dieses Objekt und diesen bestimmten Zweck gebunden, aber ich vermag nicht vorherzusagen, wie es sich verhalten wird, wenn Ihr die Gruft erreicht.\n\nSeid auf der Hut, wenn Ihr ankommt. Niemand weiß, was geschehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[86970] = { id = 86970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überprüfung der Hypothese", description = "Ich denke, es ist klug, dass wir dieses Gerät erst einmal testen, bevor Ihr in die Dunkelheit der Gruften eintaucht. Bringt die Fackel an den Rand der magischen Dunkelheit und aktiviert sie. Findet heraus, ob sie ihren Zweck erfüllt und für Beleuchtung sorgt. Und findet vor allem heraus, wie sie sich verhält, wenn sie dieser Magie ausgesetzt ist.\n\nDieses Totem ist an einen bestimmten Zweck gebunden und sollte somit gezwungen sein, sich an diesen Zweck zu halten. Aber das lässt sich erst betätigen, wenn wir dort sind und diese Hypothese überprüfen.", sourceObjective = "Begebt Euch zum Eingang der Karazhangruften, benutzt die verzauberte Feuerbrandfackel und schaut, was passiert. Kehrt zu Agentin Keanna zurück, nachdem Ihr den Test abgeschlossen habt.", progress = "Was hat der Test ergeben?", completion = "Das sind doch gute Nachrichten. Die Fackel hat nicht nur erfolgreich die schwächere Dunkelheit außerhalb der Gruft vertrieben, sondern durch die Bindung wurde sie auch in die Gruft getrieben, um dort weiter ihren Zweck zu erfüllen.\n\nNachdem die bösartige Dunkelheit außerhalb der Gruft verschwunden ist, könnt Ihr sie sicher betreten. Der Geschichte dieses Mannes nach zu urteilen, ist ungewiss, was Ihr im Inneren vorfinden werdet, also seid vorsichtig.\n\nViel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[86971] = { id = 86971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuriose Karazhankuriositäten!", description = "Jetzt, da Ihr einen Weg in die Gruft gefunden habt, möchte ich Euch um einen Gefallen bitten. Nur zum Verständnis: Ich bin Archäologe und arbeite für die Königliche Bibliothek von Sturmwind. Ich sammle Artefakte und Relikte aus aller Welt für akademische Zwecke und Studien und bin sehr an jeglichen Kuriositäten interessiert, die Ihr in den Tiefen der Gruft finden könntet. Bringt mir alles, was Ihr als interessant erachtet, und ich werde Euch gut entlohnen.", sourceObjective = "Bringt Harrison Jones am Gebirgspass der Totenwinde eine Karazhankuriosität.", progress = "Was habt Ihr für mich, {name}?", completion = "Das ist ein großartiges Fundstück! Für den Fall, dass Ihr noch mehr solcher Artefakte findet, bringt sie mir hierher. Ich werde dafür sorgen, dass Ihr für Eure Bemühungen angemessen entschädigt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[86972] = { id = 86972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuriose Karazhankuriositäten!", description = "Jetzt, da Ihr einen Weg in die Gruft gefunden habt, möchte ich Euch um einen Gefallen bitten. Nur zum Verständnis: Ich bin Archäologe und arbeite für die Königliche Bibliothek von Sturmwind. Ich sammle Artefakte und Relikte aus aller Welt für akademische Zwecke und Studien und bin sehr an jeglichen Kuriositäten interessiert, die Ihr in den Tiefen der Gruft finden könntet. Bringt mir alles, was Ihr als interessant erachtet, und ich werde Euch gut entlohnen.", sourceObjective = "Bringt Harrison Jones am Gebirgspass der Totenwinde eine Karazhankuriosität.", progress = "Denkt daran: Ich bin auf der Suche nach allen Artefakten oder Schätzen, die Ihr finden könnt. In dieser Gruft gibt es unermessliche Kostbarkeiten, also haltet die Augen offen!", completion = "Das ist ein großartiges Fundstück! Für den Fall, dass Ihr noch mehr solcher Artefakte findet, bringt sie mir hierher. Ich werde dafür sorgen, dass Ihr für Eure Bemühungen angemessen entschädigt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[87283] = { id = 87283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die lila Tasche", description = "Ihr habt eine kleine lila Tasche gefunden, die das Zeichen der Kirin Tor aufweist. Trotz Eurer Anstrengungen scheint es unmöglich, die Tasche zu öffnen und zu sehen, was sich darin befindet. Der Zettel, den Ihr bei dem Abenteurer gefunden habt, deutet darauf hin, dass sie dem Erzmagier Kir-Moldir von Dalaran gehört. Es könnte sich für Euch lohnen, den Erzmagier aufzusuchen und ihm seinen Besitz zurückzugeben... und die versprochene Belohnung einzufordern.", sourceObjective = "Sucht Erzmagier Tarsis Kir-Moldir auf und bringt ihm die lila Tasche zurück.", progress = "Der Erzmagier scheint Euch nicht zu hören...", completion = "Was habt Ihr da? Ist das... Ist das möglich?\n\n<Der Erzmagier entreißt Euch hastig die Tasche. Er flüstert eine Beschwörungsformel und leert den Inhalt in seine Hände. Dabei kommen zwei kleine rote Edelsteine zum Vorschein.>\n\nDie Augen! Ja, die Augen! Ich habe sie! Danke. Bitte, lasst mich jetzt allein... Jetzt geht schon! Verschwindet, bevor ich gezwungen bin, Euch zu vernichten!\n\n<Der entschlossene Blick in seinen Augen verrät Euch, dass er es ernst meint. Während Ihr Euch zurückzieht, wendet sich der Erzmagier ab, beugt sich vor und drückt die Edelsteine fest an seine Brust.>", sourceObjectiveStatus = "unverified-source-field" }
quests[87360] = { id = 87360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Niedergang Kel'Thuzads", description = "Das Phylakterium ist alles, was vom Herrscher Naxxramas' übrig bleibt. Nach Eurem pflichtgemäßen Ermessen, müsstet Ihr das Phylakterium zerstören, um somit einem erneuten Aufbäumen des Lichs vorzubeugen. Glücklicherweise hört Ihr nur selten auf Eure innere Stimme der Vernunft.\n\nBei der Kapelle des hoffnungsvollen Lichts wird Euch irgendjemand mit Sicherheit ein Vermögen für dieses Artefakt bezahlen. Wen kümmert es schon, ob Kel'Thuzad eines Tages wieder von Neuem erstarkt?", sourceObjective = "Bringt Kel'Thuzads Phylakterium zur Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "HEILIGES LICHT! Was ist denn in Euch gefahren, Junge?", completion = "Ich hätte mir nie erträumt, dass ich das eines Tages mal zu Gesicht bekommen sollte...\n\n<Vater Montoy scheint lüstern zu geifern.>\n\nOh ja, Ihr sollt entlohnt werden, mein Junge. Reichlich entlohnt. Gebt es mir. Jetzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[87361] = { id = 87361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Ruhe gebettet", description = "Das dem Schatten der Verdammnis entnommene Herz pulsiert schwach und vibriert.\n\nAls Ihr es in Eure Tasche stecken wollt, überkommt Euch ein überwältigendes Gefühl von Wut, Angst, Furcht und dann... Traurigkeit.\n\nWährend diese Gefühle abklingen, habt Ihr das Gefühl, als hättet Ihr gerade ein anderes Leben gelebt.\n\nVielleicht kann jemand in der Kapelle des hoffnungsvollen Lichts etwas Licht in das bringen, was Ihr gerade gefühlt habt.", sourceObjective = "Findet heraus, ob Euch jemand in der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern helfen kann.", progress = "Ihr müsst nichts erklären, {name}.\n\nEure Anwesenheit hier und diese Kugel sagen mir alles, was ich wissen muss.\n\nDie Dunkelheit hat Euch auf die Probe gestellt, {name}.\n\nIhr habt Glück gehabt. Mit der Geißel und ihren Flüchen ist nicht zu spaßen.\n\nDas Licht folgt Euch.", completion = "So gut wie niemand, der diese verfluchten Gegenstände berührt, ist noch im Besitz seiner geistigen Kräfte.\n\n<Obwohl sein Gesichtsausdruck unverändert bleibt, laufen ihm Tränen über das Gesicht, als Ihr ihm das Herz überreicht.>\n\nAh... Hier will jemand nicht loslassen. Diese Person entstammt der {class}-Klasse... so wie Ihr...\n\n{name}, wenn Ihr bereit seid, eine solche Bürde zu tragen, kann ich Euch vielleicht helfen. Ich kann diese unruhige Seele in Eure Rüstung eingravieren...\n\nGenau wie das Gewicht der Welt trägt sich eine Seele am besten auf den Schultern.", sourceObjectiveStatus = "unverified-source-field" }
quests[87362] = { id = 87362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung beginnt in der Dunkelheit", description = "Naxxramas stellt eine Bedrohung dar, wie Ihr sie nie zuvor erlebt habt. Es ist der Sitz der Macht Kel'Thuzads und birgt Schrecken, die selbst den kampferprobtesten Kriegern der Argentumdämmerung unbekannt sind.\n\nNehmt dieses Siegel.\n\nWenn Ihr Euch in die Nekropole wagt, tragt Ihr die Last unserer Hoffnungen, {name}. Es ist also nur recht, dass Ihr auch unsere Stärke tragt.", sourceObjective = "Erhaltet das Siegel der Dämmerung.", completion = "Dieses Siegel verstärkt die Ausrüstung, die ihr in Naxxramas erbeutet.\n\nVerliert es nicht aus den Augen und nutzt es gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[87364] = { id = 87364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Sack zumachen", sourceObjective = "Sammelt die Überreste des Heldenmuts in Naxxramas ein.", progress = "Ehrlich gesagt gibt es vielleicht eine Möglichkeit, die Kraft Eures Siegels zu steigern, {name}.\n\nWenn man die Überreste mächtiger Gefolgsleute der Geißel aufbereitet, wird ein kleiner Teil der heiligen Energie nicht nur bewahrt, sondern auch verarbeitungsfähig gemacht. Diese Energie kann zu Stärke geschmiedet werden.\n\nDringt tiefer in Naxxramas ein und bringt mir die Überreste dieser Gefolgsleute der Geißel. Im Gegenzug kann ich Euer Siegel stärken.", completion = "Das war gute Arbeit, {name}.\n\nIch frage mich, wie viele davon von unseren gefallenen Brüdern stammen? Waren sie noch irgendwo da drin? Ich tröste mich mit der Annahme, dass es ihr Wunsch wäre, dass wir andere davon abhalten, so zu werden wie sie. Auch wenn das nur ein schwacher Trost ist.\n\nLast mich jetzt Euer Siegel stärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[87365] = { id = 87365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mut erwächst durch Wagemut", sourceObjective = "Sammelt die Überreste des Heldenmuts in Naxxramas ein.", progress = "Es ist noch ein langer Weg, bis Euer Siegel sein volles Potenzial erreicht. Bringt mir mehr Überreste des Heldenmuts, und ich werde Euch weiterhin mit der Kraft versorgen, unsere Welt zu beschützen.\n\nDenkt daran, dass die Toten keine Gerechtigkeit einfordern können. Es ist die Pflicht der Lebenden, dies für sie zu tun.", completion = "Gut gemacht. Das wird auch dieses Mal nicht lange dauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[87366] = { id = 87366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritterzeit", sourceObjective = "Sammelt die Überreste des Heldenmuts in Naxxramas ein.", progress = "Jeder getötete Diener der Geißel ist eine befreite Seele, {name}. Vergesst niemals, dass Ihr das Richtige tut. Selbst wenn, nein, besonders dann, wenn der Kampf hoffnungslos erscheint. Solange wir uns widersetzen, können die Armeen des Lichkönigs uns nicht aufhalten.\n\nIhr scheint das Vorgehen verinnerlicht zu haben. Besorgt mir mehr Überreste, und ich werde Euer Siegel erneut stärken.", completion = "Die Gerechtigkeit trachtet nicht nach Belohnung, {name}.\n\nAber Ihr schon. Bitte nehmt dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[87367] = { id = 87367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Licht", sourceObjective = "Erhaltet das Siegel der Dämmerung.", progress = "Jedes Mal, wenn wir Euer Siegel stärken, kommen wir dem Ende von Kel'Thuzads Vorstoß einen Schritt näher.\n\nWenn Ihr stark bleibt, werden wir Azeroth im Handumdrehen vom Lichkönig und seinen Gefolgsleuten befreit haben.", completion = "Ihr seid eine Heldenlegende, {name}. Der Aschenbringer selbst wäre beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87368] = { id = 87368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Produkt des Glaubens", sourceObjective = "Erhaltet das Siegel der Dämmerung.", progress = "Mich schaudert es bei dem Gedanken an die Schrecken, denen Ihr ausgesetzt wart, um so weit zu kommen. Ihr seid ein Vorbild für die Argentumdämmerung, und ich kann nur beten, dass Ihr uns weiterhin auf diese Weise unterstützt.\n\nBringt mir mehr Überreste des Heldenmuts und ich werde Euer Siegel stärken. Ich glaube, es liegt noch ein weiter Weg vor Euch, bevor Ihr Euer volles Potenzial ausschöpfen könnt.", completion = "Gut gemacht, {name}. Die Gefallenen zu läutern, wäre für sich genommen schon die Mühe wert, selbst wenn keine Belohnung versprochen wäre.\n\nAber das gilt natürlich nicht für Euch! Nehmt Euer frisch gestärktes Siegel.", sourceObjectiveStatus = "unverified-source-field" }
quests[87369] = { id = 87369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kultivierter Glaube", sourceObjective = "Erhaltet das Siegel der Dämmerung.", progress = "Ich hätte nie gedacht, dass der Scharlachrote Kreuzzug und die Argentumdämmerung ihre Differenzen beilegen und für ein gemeinsames Ziel kämpfen könnten. Und doch sind wir hier.\n\nIhr habt wieder und wieder bewiesen, dass sich das Risiko gelohnt hat. Bringt mir mehr Überreste des Heldenmuts, Champion. Ich habe das Gefühl, dass wir kurz davor stehen, Kel'Thuzad und seinen Schergen den Todesstoß zu versetzen.", completion = "Ich kann Euch nicht genug danken. Aber ich beweise meine Dankbarkeit, indem ich Euer Siegel stärke.", sourceObjectiveStatus = "unverified-source-field" }
quests[87377] = { id = 87377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit der Ruhe", description = "Bringt mir alle verlorenen Seelen, die Euren Weg kreuzen, {name}.\n\nOder besser gesagt: Ihr MÜSST sie mir bringen.\nMEINE Pflicht ist es, hierzubleiben und die Seelen der Verlorenen zu führen. EURE Pflicht ist es, sie mir zu bringen.\n\nUnd lasst Euch gesagt sein: Kümmert Euch nie um mehr als eine Seele auf einmal. Glaubt mir, Eure Seele kann nur eine bestimmte Menge von ihnen verkraften, und Euer Verstand... nun ja... noch weniger.\n\nDiese Bürde lastet nun auf Euch. Weil Ihr es könnt, müsst Ihr es tun.\n\nBetrachtet es als moralische Verpflichtung.", sourceObjective = "Bringt Bruder Luctus in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern ein weiteres Herz der Verdammnis.", progress = "Da die Geißel niemals ruht, dürfen wir es auch nicht, {name}.", completion = "{name}, jedes wiedergefundene Herz erfüllt mich mit Demut. Einige dieser Seelen stammen von mächtigen Kriegern. Einige schienen unbesiegbar zu sein... und doch... sind sie gefallen.\n\nDie Geißel hat sie überwältigt, die Verderbnis hat sich in ihren Köpfen festgesetzt, und in einigen Fällen haben sie sich ihr sogar bereitwillig unterworfen.\n\nEine so große Stärke... einfach ausgemerzt.\n\nAber jetzt wahren sie dank Eurer Hilfe ihren letzten Rest an Tapferkeit.\n\nOhne Euch würden die Schrecken ihres Todes die Heldentaten ihres Lebens überwiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87433] = { id = 87433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plattenhandschuhe der Argentumdämmerung" }
quests[87434] = { id = 87434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plattenhandschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
quests[87435] = { id = 87435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kettenhandschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
