quests[87437] = { id = 87437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lederhandschuhe der Argentumdämmerung" }
quests[87438] = { id = 87438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lederhandschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
quests[87439] = { id = 87439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoffhandschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
quests[87440] = { id = 87440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoffhandschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
quests[87441] = { id = 87441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[87442] = { id = 87442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[87443] = { id = 87443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[87444] = { id = 87444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert und kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[87459] = { id = 87459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Aktivitäten", description = "Während wir uns hier hübsch mit dem Scharlachroten Kreuzzug vertragen, verhalten sie sich an anderer Stelle höchst verdächtig. Einige meiner Kontakte in Tirisfal sprechen von einem unverfrorenen Einfall des Scharlachroten Kreuzzugs in das Herz von Undercity selbst. Wir haben zudem Berichte von unseren Spähtrupps erhalten, dass große Karawanen gesichtet wurden, die Vorräte durch die Pestländer transportieren. Ein Elitetrupp des Scharlachroten Kreuzzugs wurde in der Nähe des Außenpostens der Kreuzzügler in Tirisfal aufgedeckt, zwischen Balnirs Bauernhof und dem Giftwebertal. Seid doch so gut und seht nach, was Ihr dort herausfinden könnt.", sourceObjective = "Begebt Euch in das Gebiet in der Nähe des Außenpostens der Kreuzzügler nordwestlich des Bollwerks in Tirisfal und untersucht die Anzeichen auf neuerliche Aktivitäten des Scharlachroten Kreuzzugs. Bringt sämtliche Informationen, die Ihr finden könnt, zu Leonid Barthalomew dem Geachteten.", progress = "Wie läuft es mit Eurem Auftrag, {name}?", completion = "So so. Es scheint, als hätte der Kreuzzug jemanden aus der Stadt entführt, und sogar jemanden von Bedeutung. Das ist überaus bedenklich. Vielen Dank, {name}. Haltet vorerst die Füße still und sprecht mit niemandem hierüber. Unsere Allianz mit dem Scharlachroten Kreuzzug ist unsicher, doch wir brauchen momentan jede Hilfe, die wir kriegen können, um der Bedrohung durch Naxxramas Einhalt zu gebieten.\n\nIch werde dem selbst nachgehen. Ich melde mich vermutlich noch einmal bei Euch für weitere Hilfe in dieser Sache. Bis dahin, geht mit dem Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[87493] = { id = 87493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unruhe bei Tyrs Hand", description = "Es gibt interessante Entwicklungen, {name}. Während der Scharlachrote Kreuzzug sich auf Naxxramas konzentrierte, gab es wohl einigen Aufruhr in den Rängen von Tyrs Hand. Die Einzelheiten sind noch unklar, aber soweit wir wissen, kam es zu Scharmützeln innerhalb des Kreuzzugs.\n\nIch würde Euch gerne zum Lager westlich von Tyrs Hand schicken, um die Situation für uns einzuschätzen. Lasst uns also schnellstmöglich wissen, was Ihr findet.", sourceObjective = "Späht den Scharlachroten Stützpunkt westlich von Tyrs Hand in den Östlichen Pestländern aus und versucht herauszufinden, was mit den Truppen des Kreuzzugs dort passiert.", completion = "Seid gegrüßt, {name}. Ich... bin froh, Euch wiederzusehen. Wenn ich auch wünschte, die Umstände wären bessere.", sourceObjectiveStatus = "unverified-source-field" }
quests[87497] = { id = 87497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spaltung", description = "Ich komme gleich zum Punkt: Die Enklave von Tyrs Hand steht nicht mehr unter unserer Kontrolle. Während wir in Naxxramas waren, traf eine Streitmacht feindlicher Kreuzzügler aus Stratholme ein und riss die Kontrolle über die Festung an sich. Uns wurde der Eintritt verwehrt, und keiner der Botschafter, die wir hineinschickten, kehrte zurück.\n\nIch hasse es, um Hilfe von außen zu bitten, doch etwas stimmt hier ganz und gar nicht, und ich weiß nicht, ob wir die Enklave allein zurückerobern können.", sourceObjective = "Sprecht mit Beatrix, um mehr über die Situation in der Scharlachroten Enklave bei Tyrs Hand zu erfahren, und meldet Euch wieder bei Leonid Barthalomew dem Geachteten in der Kapelle des hoffnungsvollen Lichts, sobald Ihr mehr über die Vorgänge wisst.", completion = "Die Entwicklungen bei Tyrs Hand sind... gewiss interessant. Abbendis ist vermutlich tot, Balnazzar zurückgekehrt. Obwohl ein Teil von mir sich am liebsten zurücklehnen und dem Scharlachroten Kreuzzug dabei zusehen möchte, wie er erntet, was er gesät hat, so habe ich auch das Gefühl, dass die Argentumdämmerung so oder so in den Konflikt hineingezogen wird. So geschwächt wir nach der Kampagne gegen Naxxramas auch sind, Lord Tyrosus würde es bevorzugen, wenn unsere Einmischung zu unseren Bedingungen stattfindet, anstatt von außen gezwungen zu werden.\n\nAußerdem... sagtet Ihr, Inquisitor Caldoran war dort?", sourceObjectiveStatus = "unverified-source-field" }
quests[87498] = { id = 87498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharlachrote Rückeroberung", description = "<Leonids Miene verfinstert sich, als Ihr bestätigt, dass Caldoran sich im Scharlachrotem Stützpunkt aufhält. Nach einem Augenblick gewinnt er die Fassung wieder.> \n\nIch... danke Euch, {name}. Assistiert vorerst weiter Beatrix, wenn Ihr möchtet. Ich werde mich mit Lord Tyrosus besprechen und Notfallpläne entwickeln, falls die Argentumdämmerung sich direkt einmischen muss. Ich bete, dass die Situation nicht so düster ist, wie man uns vormacht, aber wenn wir einschreiten müssen, um dem Ganzen ein Ende zu setzen, dann werden wir bereit sein.", sourceObjective = "Kehrt zu Kommandantin Beatrix beim Scharlachroten Stützpunkt westlich von Tyrs Hand zurück.", completion = "Also werdet Ihr uns helfen? Ich muss gestehen, ich bin erleichtert. Ich habe Eure Fähigkeiten und die Eurer Verbündeten mit eigenen Augen gesehen und ich bin froh, Euch auf unserer Seite zu wissen. Ich hatte die Hoffnung, die Argentumdämmerung würde ihre direkte Hilfe anbieten, aber ich bin dennoch dankbar für Eure Unterstützung.\n\nSprecht mit Inquisitor Caldoran auf dem Hügel in der Nähe. Er kann Euch einweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87502] = { id = 87502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationsbeschaffung", description = "Es gefällt mir nicht, Euch als Unterstützung einzuspannen. Ihr steht mit Ketzern und Unreinen im Bunde, und es ist unter meiner und der Würde unseres heiligen Ordens, Eure Anwesenheit hier zu dulden. Dennoch... habt Ihr Euch in der Vergangenheit wohl als fähig genug erwiesen und solltet ein wirkungsvolles Werkzeug für unsere Zwecke darstellen.\n\nGeht nach Tyrs Hand und späht die Kathedrale dort aus, bevor Ihr tiefer nach Neu-Avalon vordringt und die hintere Festung und den Magierturm ausspäht. Meldet Euch dann unverzüglich hier zurück und berichtet mir. Wir müssen wissen, womit wir es zu tun haben.", sourceObjective = "Betretet Tyrs Hand in den Östlichen Pestländern und späht die zentrale Kathedrale sowie den Magierturm und die Festung innerhalb von Neu-Avalon aus, bevor Ihr zu Baelin Caldoran im Scharlachroten Stützpunkt zurückkehrt.\n\nEin direktes Eindringen ist möglich, aber gefährlich. Sprecht mit Inquisitorin Jociphine im Scharlachroten Stützpunkt, wenn Ihr eine subtilere Vorgehensweise wünscht.", completion = "<Caldoran raunt Euch schroff an, als Ihr Euren Bericht abschließt.>\n\nDie Ansammlung der Truppen in Neu-Avalon ist besorgniserregend, doch ihre Zahlen sind nicht unbezwingbar.\n\nEs scheint außerdem, dass Dathrohan, oder besser gesagt Balnazzar, seine Macht in der zentralen Kathedrale festigt. Sein Gebrauch von dunkler Magie, um den Eingang zu versiegeln, bestätigt, dass er da drin etwas ausheckt. Dieses Monster entweiht unseren heiligen Boden und dafür werde ich ihn eigenhändig vernichten. Das schwöre ich bei meinem Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[87506] = { id = 87506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung schwächen", description = "Während Eurer Abwesenheit konnten wir unsere Angriffspläne auf Tyrs Hand fertigstellen. Wir werden einen frontalen Ansturm mit einem Flankenangriff kombinieren, den ich selbst anführen werde. Doch bevor wir zuschlagen, müssen wir ihre Frontverteidigung schwächen. Ich schicke Euch zurück zu Tyrs Hand, um so viele feindliche Belagerungskommandanten auszuschalten wie möglich, denn sie sind die Schlüsselakteure der Verteidigung der Enklave.\n\nIch werde mich meinen Truppen an deren Position jetzt anschließen. Ihr werdet also Kommandantin Beatrix Bericht erstatten, wenn Ihr zurückkehrt.\n\nScheitert nicht.", sourceObjective = "Betretet Tyrs Hand in den Östlichen Pestländern und tötet drei scharlachrote Belagerungskommandanten.", completion = "Caldoran und sein Einsatztrupp haben das Signal gegeben, dass sie vor Ort und bereit für einen direkten Angriff sind.\n\nWährend Ihr fort wart, kam ein Bote der Argentumdämmerung an und überbrachte eine Nachricht, bevor er zügig wieder abreiste. Es scheint Ärger in der Kapelle des hoffnungsvollen Lichts zu geben. Ihr werdet dort also dringend gebraucht. Ich kann nicht noch mehr von Euch verlangen, denn Ihr wart uns bereits eine unbezahlbare Hilfe. Ich danke Euch für alles, {name}. Wir sind nun so bereit wie nur möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[87508] = { id = 87508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichtet Lord Tyrosus", description = "Bitte, {name}, ein Bote traf soeben ein. Ihr müsst schnellstmöglich zur Kapelle des hoffnungsvollen Lichts zurückkehren! Wir werden angegriffen und Lord Maxwell Tyrosus hat nach Eurer sofortigen Anwesenheit verlangt.", sourceObjective = "Sprecht mit Lord Maxwell Tyrosus an der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.", completion = "Wir wurden angegriffen! Eine drachenartige... Monstrosität schoss aus der Richtung der Scharlachroten Enklave heran und traf uns schwer. Ich habe schon Drachen gesehen, aber so etwas ist mir noch nie unter die Augen gekommen.\n\nDas Seltsamste daran ist, dass der Drache einfach... verschwand. Er traf uns mit einem einzigen, grauenvollen Hieb und flog einfach davon. Sicher, das ist ein Segen. Aber es ist auch zutiefst beunruhigend. Wir wurden vollkommen unvorbereitet getroffen. Er hätte unvorstellbaren Schaden anrichten können, entschied sich aber wohl dagegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87509] = { id = 87509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Dämmerung", description = "Ungeachtet des Grundes, warum die Bestie sich zur Enklave zurückzog, werden wir ihr keine zweite Gelegenheit geben, uns zu vernichten. Wie es aussieht, sind wir gezwungen, den vollen Zorn der Argentumdämmerung darauf zu richten, der Bedrohung in der Scharlachroten Enklave ein Ende zu machen.\n\nKehrt zum Scharlachroten Stützpunkt zurück und nehmt wieder Kontakt zu Beatrix auf. Sagt ihr, dass wir sie unterstützen werden... vorerst.", sourceObjective = "Meldet Euch wieder bei Kommandantin Beatrix im Scharlachroten Stützpunkt in den Östlichen Pestländern und bereitet Euch auf die Rückeroberung der Scharlachroten Enklave vor.", completion = "Irgendeine Bestie hat die Kapelle des hoffnungsvollen Lichts angegriffen? Das ist mutig von Balnazzar. Zu mutig, denn die Argentumdämmerung hat sich unserer Sache nun angeschlossen. Ich will ehrlich mit Euch sein. Ich bin nicht erleichtert, dass sie uns unterstützen. Ich glaube nicht, dass wir die Enklave jetzt noch mit unseren eigenen Streitkräften einnehmen könnten.\n\nEs wird ernst, {class}. Macht Euch bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[87516] = { id = 87516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kopf abschlagen", description = "Unsere Truppen sind versammelt und werden sich in Position begeben, um den Frontalangriff zu beginnen, während die Euren sich über den Bergpfad hinter die Kathedrale schleichen.\n\nSobald Ihr hineingelangt, bahnt Euch den Weg zur Abtei und läutet die Glocke, um das Signal zum Angriff zu geben.\n\nIhr werdet mitten im Schlachtgetümmel aushalten müssen, bis wir eintreffen und Euch ablösen, gebt also Acht.", sourceObjective = "Betretet die Scharlachrote Enklave über den Bergpfad und greift die Verteidiger von Tyrs Hand an. Läutet die Glocke der Abtei, um für Verwirrung zu sorgen, und gebt den Truppen von Beatrix das Signal zum Angriff.\n\nNachdem die Glocke geläutet ist, stellt Euch Balnazzar und vernichtet ihn.", progress = "Das wäre beinahe ein komplettes Desaster geworden...", completion = "Wir wurden verraten! Nachdem Balnazzar fiel, übernahm Beatrix die Kontrolle über die führerlosen Verteidiger und richtete ihre neuerrungenen Streitkräfte gegen uns! Die Verluste waren schwer, doch wir haben mit aller Kraft zurückgeschlagen und konnten uns zurückziehen und neu sammeln. Wir befürchteten das Schlimmste, bis unsere Späher berichteten, dass Ihr hier seid.\n\nIch weiß, was Beatrix und Caldoran für ein Spiel treiben, aber inzwischen bin ich bereit, jeden in einer roten Uniform niederzustrecken und dem Licht alles weitere zu überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87517] = { id = 87517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot = Tot", description = "Wie es scheint, ist das Monstrum, das die Kapelle des hoffnungsvollen Lichts angegriffen hat, Caldorans Schoßhündchen, und der Angriff auf die Kapelle war lediglich ein Hinterhalt, mit dem er unsere Truppen hervorlocken und zu diesem Ausfall bewegen wollte. Caldoran und Beatrix wollten uns als Ablenkung nutzen, um ihren Rivalen Balnazzar auszuschalten und sich dann gegen uns zu wenden und uns aus den Pestländern zu tilgen, nachdem sie die Kontrolle wiedererlangt hatten.\n\nUns fehlen zu viele Antworten und es sieht nicht gut aus, aber wir werden diese Köter für ihren Verrat niederstrecken.", sourceObjective = "Stürzt Euch in die Schlacht und erlangt Zugang zum inneren Bereich der Scharlachroten Enklave. Stellt Euch den Truppen von Hochkommandantin Beatrix und besiegt sie, dann tötet den Drachen Solistrasza hinter der inneren Mauer der Enklave.", completion = "Was wir hier entdeckt haben, ist grauenvoll. Eine neue Seuche? Ein lichtgebundener Drache? Den Frommen die Seelen entziehen, um ihre lichterfüllten Waffen damit zu nähren? Solch ein Missbrauch des Lichts ist abstoßend und ich erschaudere beim Gedanken, welche anderen Mächte Caldoran noch zur Verfügung stehen. Die Weise, wie er Balnazzar niederstreckte, sagt mir, dass er etwas ausgeheckt hat. Solch rohe Kraft weisen nicht einmal die stärksten Paladine auf.\n\nSo oder so, das hat jetzt ein Ende. Für diese Verbrechen gibt es keine Vergebung.", sourceObjectiveStatus = "unverified-source-field" }
quests[87518] = { id = 87518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Obersten Kreuzzüglers", description = "Der Weg, der jetzt vor uns liegt, ist einfach und brutal. Dringt in das innere Sanktum der Scharlachroten Enklave vor und stellt den selbsternannten \"Obersten Kreuzzügler\" Baelin Caldoran. Richtet ihn für seine Verbrechen. Wir werden hierbleiben und diese Position sichern, damit Euch keine übriggebliebenen Truppen in den Rücken fallen.\n\nFührt dieses Monster der Gerechtigkeit zu.", sourceObjective = "Tötet den Obersten Kreuzzügler Baelin Caldoran im inneren Sanktum der Scharlachroten Enklave.", completion = "Caldoran ist fort, doch es ist ein bittersüßer Sieg. Es war ein blutiger Tag. Wir haben Gutes getan. Die übrigen Truppen des Scharlachroten Kreuzzugs sind zerschlagen und die Scharlachrote Enklave steht in Flammen. In den Pestländern ist noch viel zu tun, doch wenigstens haben wir vorerst einen Gegner weniger, um den wir uns Sorgen machen müssen. Wenn es nach mir geht, ist das Grund genug zum Feiern. \n\nFür das Licht! Für Lordaeron! Für die Dämmerung!", sourceObjectiveStatus = "unverified-source-field" }
quests[88654] = { id = 88654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung" }
quests[88714] = { id = 88714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit der Ruhe", description = "Bringt mir alle verlorenen Seelen, die Euren Weg kreuzen, {name}.\n\nOder besser gesagt: Ihr MÜSST sie mir bringen.\nMEINE Pflicht ist es, hierzubleiben und die Seelen der Verlorenen zu führen. EURE Pflicht ist es, sie mir zu bringen.\n\nUnd lasst Euch gesagt sein: Kümmert Euch nie um mehr als eine Seele auf einmal. Glaubt mir, Eure Seele kann nur eine bestimmte Menge von ihnen verkraften, und Euer Verstand... nun ja... noch weniger.\n\nDiese Bürde lastet nun auf Euch. Weil Ihr es könnt, müsst Ihr es tun.\n\nBetrachtet es als moralische Verpflichtung.", sourceObjective = "Bringt Bruder Luctus in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern ein weiteres Herz der Verdammnis.", progress = "Da die Geißel niemals ruht, dürfen wir es auch nicht, {name}.", completion = "{name}, jedes wiedergefundene Herz erfüllt mich mit Demut. Einige dieser Seelen stammen von mächtigen Kriegern. Einige schienen unbesiegbar zu sein... und doch... sind sie gefallen.\n\nDie Geißel hat sie überwältigt, die Verderbnis hat sich in ihren Köpfen festgesetzt, und in einigen Fällen haben sie sich ihr sogar bereitwillig unterworfen.\n\nEine so große Stärke... einfach ausgemerzt.\n\nAber jetzt wahren sie dank Eurer Hilfe ihren letzten Rest an Tapferkeit.\n\nOhne Euch würden die Schrecken ihres Todes die Heldentaten ihres Lebens überwiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88715] = { id = 88715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit der Ruhe", description = "Bringt mir alle verlorenen Seelen, die Euren Weg kreuzen, {name}.\n\nOder besser gesagt: Ihr MÜSST sie mir bringen.\nMEINE Pflicht ist es, hierzubleiben und die Seelen der Verlorenen zu führen. EURE Pflicht ist es, sie mir zu bringen.\n\nUnd lasst Euch gesagt sein: Kümmert Euch nie um mehr als eine Seele auf einmal. Glaubt mir, Eure Seele kann nur eine bestimmte Menge von ihnen verkraften, und Euer Verstand... nun ja... noch weniger.\n\nDiese Bürde lastet nun auf Euch. Weil Ihr es könnt, müsst Ihr es tun.\n\nBetrachtet es als moralische Verpflichtung.", sourceObjective = "Bringt Bruder Luctus in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern ein weiteres Herz der Verdammnis.", progress = "Da die Geißel niemals ruht, dürfen wir es auch nicht, {name}.", completion = "{name}, jedes wiedergefundene Herz erfüllt mich mit Demut. Einige dieser Seelen stammen von mächtigen Kriegern. Einige schienen unbesiegbar zu sein... und doch... sind sie gefallen.\n\nDie Geißel hat sie überwältigt, die Verderbnis hat sich in ihren Köpfen festgesetzt, und in einigen Fällen haben sie sich ihr sogar bereitwillig unterworfen.\n\nEine so große Stärke... einfach ausgemerzt.\n\nAber jetzt wahren sie dank Eurer Hilfe ihren letzten Rest an Tapferkeit.\n\nOhne Euch würden die Schrecken ihres Todes die Heldentaten ihres Lebens überwiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88716] = { id = 88716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit der Ruhe", description = "Bringt mir alle verlorenen Seelen, die Euren Weg kreuzen, {name}.\n\nOder besser gesagt: Ihr MÜSST sie mir bringen.\nMEINE Pflicht ist es, hierzubleiben und die Seelen der Verlorenen zu führen. EURE Pflicht ist es, sie mir zu bringen.\n\nUnd lasst Euch gesagt sein: Kümmert Euch nie um mehr als eine Seele auf einmal. Glaubt mir, Eure Seele kann nur eine bestimmte Menge von ihnen verkraften, und Euer Verstand... nun ja... noch weniger.\n\nDiese Bürde lastet nun auf Euch. Weil Ihr es könnt, müsst Ihr es tun.\n\nBetrachtet es als moralische Verpflichtung.", sourceObjective = "Bringt Bruder Luctus in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern ein weiteres Herz der Verdammnis.", progress = "Da die Geißel niemals ruht, dürfen wir es auch nicht, {name}.", completion = "{name}, jedes wiedergefundene Herz erfüllt mich mit Demut. Einige dieser Seelen stammen von mächtigen Kriegern. Einige schienen unbesiegbar zu sein... und doch... sind sie gefallen.\n\nDie Geißel hat sie überwältigt, die Verderbnis hat sich in ihren Köpfen festgesetzt, und in einigen Fällen haben sie sich ihr sogar bereitwillig unterworfen.\n\nEine so große Stärke... einfach ausgemerzt.\n\nAber jetzt wahren sie dank Eurer Hilfe ihren letzten Rest an Tapferkeit.\n\nOhne Euch würden die Schrecken ihres Todes die Heldentaten ihres Lebens überwiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88721] = { id = 88721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Freund der Dämmerung", description = "Seid gegrüßt. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 30 Insignien der Dämmerung und 30 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88722] = { id = 88722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Wohlwollen der Dämmerung", description = "Seid gegrüßt. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem ziemlich unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 20 Insignien der Dämmerung und 20 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88723] = { id = 88723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Respekt der Dämmerung", description = "Seid gegrüßt. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen respektvollen Ruf genießt, kann Gegenstände zu einem recht angemessenem Preis erwerben. Ich würde Euch zu einem Geschäft raten!", sourceObjective = "Für 7 Insignien der Dämmerung und 7 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", progress = "Wählt mit Bedacht. Es gibt keine Rückerstattung.", completion = "Schönen Tag noch, {name}. Es war mir ein Vergnügen, mit Euch Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88724] = { id = 88724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überragende Kampfausrüstung - Ehrfurcht der Dämmerung", description = "Seid gegrüßt. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen einen Preisnachlass. Ich würde Euch zu einem Geschäft raten!", sourceObjective = "Für 6 Insignien der Dämmerung und 6 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", progress = "Wählt mit Bedacht. Es gibt keine Rückerstattung.", completion = "Schönen Tag noch, {name}. Es war mir ein Vergnügen, mit Euch Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88725] = { id = 88725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Freund der Dämmerung", description = "Seid gegrüßt. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem extrem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 110 Insignien der Dämmerung und 110 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88726] = { id = 88726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Wohlwollen der Dämmerung", description = "Seid gegrüßt. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem extrem unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 75 Insignien der Dämmerung und 75 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88727] = { id = 88727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Respekt der Dämmerung", description = "Seid gegrüßt. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen respektvollen Ruf genießt, muss für epische Gegenstände noch immer einen sehr hohen Preis bezahlen. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", sourceObjective = "Für 45 Insignien der Dämmerung und 45 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88728] = { id = 88728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epische Kampfausrüstung - Ehrfurcht der Dämmerung", description = "Seid gegrüßt. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen garantiert den besten Preisnachlass. Ich würde Euch zu einem Geschäft raten.", sourceObjective = "Für 27 Insignien der Dämmerung und 27 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88729] = { id = 88729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramaladnis eisiger Griff", description = "Den Ring wiederherzustellen, scheint eine ziemliche Herausforderung zu sein, {name}. Seht Ihr, er wurde hergestellt aus Runen, die sich in Bauwerken der Geißel finden - in Bauwerken wie Naxxramas. Es könnten noch weitere Materialien gebraucht werden, aber Eure Hauptsorge sollte es sein, diese gefrorenen Runen zu beschaffen. Ich kann dem Ring seinen alten Glanz zurückgeben, wenn Ihr mir bringt, was ich dazu benötige.", sourceObjective = "Korfax in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern möchte, dass Ihr ihm 1 gefrorene Rune, 1 blauen Saphir und 1 Arkanitbarren bringt.", progress = "Gefrorene Runen findet man wahrscheinlich in Naxxramas.", completion = "Ramaladni selbst könnte es nicht besser gemacht haben! Hier ist der Ring, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88730] = { id = 88730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Einzige, das ich kann...", description = "Ihr haltet Euch für <einen Helden/eine Heldin> der Dämmerung, ja? Ich habe gesehen, wie unsere besten Soldaten von Kel'Thuzads Gefolgsleuten überrannt wurden. Wie könnte jemand, der so ahnungslos ist wie Ihr, in Naxxramas bestehen?\n\n<Wilhelm seufzt.>\n\nPah, was für eine Wahl habe ich denn? Ihr seid das Beste, das ich zur Verfügung habe. Warum sollte ich Euch nicht helfen?\n\nOmarion hat mir ein Muster hinterlassen. Es ist das Einzige, das ich kann... Ich kann ein paar Varianten dieser Hosen herstellen. Ihr müsst mich nur mit den Materialien versorgen.", sourceObjective = "Handwerker Wilhelm in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern möchte, dass Ihr ihm 2 gefrorene Runen, 2 Essenzen des Wassers, 2 blaue Saphire und 30 Goldstücke bringt.", progress = "Ihr habt nicht zufällig Omarion getroffen?", completion = "<Wilhelm wischt sich den Schweiß von der Stirn.>\n\nDas war ein hartes Stück Arbeit! Ich hoffe, die Hose gefällt Euch, {class}. Zumindest werdet ihr jetzt in einer sauberen Hose sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[88744] = { id = 88744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohliche Schatten", description = "Die schwebenden Nekropolen der Geißel belagern gleichermaßen die Territorien der Horde und der Allianz. Tanaris, die Verwüsteten Lande, Winterspring und die Brennende Steppe erzittern unter den Schatten der fliegenden Festungen.\n\nNur durch unser gemeinsames Handeln können wir sie zurückschlagen.\n\nDie Nekropolen werden durch magische Zirkel unterstützt, die sich an verschiedenen Punkten in den angegriffenen Gebieten befinden. Wir haben herausgefunden, dass wir die Verteidigung rund um die Zirkel zerstören können, indem wir die geistlosen Horden, die diese Zirkel umringen, vernichten.", sourceObjective = "Seht auf Eure Karte, um von der Geißel angegriffene Gebiete ausfindig zu machen. Geht dorthin und beschädigt eine Nekropole, indem Ihr die sie umgebenden Truppen der Geißel besiegt. Bringt 10 ihrer nekrotischen Runen zu Kommandant Thomas Helleran bei der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.", progress = "Es wird einige Zeit dauern, bis wir diese Bedrohung überwunden haben. Wie ist es Euch ergangen, {name}?", completion = "Ihr habt Euch sehr gut geschlagen, {name}. Die vielen Niederlagen werden letztlich den Fall der Geißel herbeiführen.\n\nRuht Euch etwas aus und erholt Euch. Schon bald müsst Ihr wieder an die Front zurückkehren, damit wir unsere gerade gewonnene Stellung nicht wieder verlieren.\n\nUm Euch bei Euren zukünftigen Kämpfen zu unterstützen, werden wir Euch einen unserer speziellen Gegenstände zur Verfügung stellen, sobald Ihr uns mehr nekrotische Runen bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[88745] = { id = 88745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Verdammnis", description = "Nachdem Ihr die Verteidigung der Beschwörungskreise der Geißel in den angegriffenen Gebieten ausgeschaltet habt, könnt Ihr den Akolythen, die sie beschützen, gegenübertreten.\n\nIn Wirklichkeit handelt es sich dabei nicht um richtige Wesen, sondern um Schatten, die zu den beängstigendsten Kreaturen des Lichkönigs zählen. Sie können mit Hilfe der nekrotischen Runen, die sie bei sich tragen, Gestalt annehmen und dann mit Magie oder dem Einsatz von Waffen zerstört werden.", sourceObjective = "Geht zu einem Beschwörungskreis und tötet einen Schatten der Verdammnis. Kehrt dann zu Kommandant Thomas Helleran bei der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern zurück.", completion = "Ausgezeichnete Arbeit, {name}. Sind die Schatten erst mal zerstört, ist es nur noch eine Frage der Zeit, bis der Lichkönig seine Nekropolen endgültig zurückruft und uns in Frieden lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[88746] = { id = 88746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Wetzsteine", progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, {name}. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise." }
quests[88747] = { id = 88747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Wetzsteine", progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, {name}. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise." }
quests[88748] = { id = 88748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesprungener nekrotischer Kristall", description = "Ihr entdeckt beim Körper der toten Monstrosität einen gesprungenen Kristall, der langsam mit nekrotischer Energie pulsiert.", sourceObjective = "Bringt den gesprungenen nekrotischen Kristall zu Leutnant Orrin außerhalb der Tore von Stormwind.", progress = "Ja, was gibt's?", completion = "Hm, Ihr habt das beim Körper einer der Monstrositäten gefunden?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Stormwind errichten wollten. Es ist gut, dass sie damit erfolglos waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[88749] = { id = 88749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwacher nekrotischer Kristall", description = "Ihr findet beim Körper der toten Kreatur einen Kristall, der schwache nekrotische Energie ausstrahlt.", sourceObjective = "Bringt den schwachen nekrotischen Kristall zu Leutnant Rukag im Hof von Undercity.", progress = "Kann ich Euch irgendwie weiterhelfen?", completion = "Ihr sagt, dass Ihr das bei einer der Kreaturen gefunden habt, die die Stadt angreifen?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Undercity errichten wollten. Wir müssen zukünftig sehr vorsichtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[88882] = { id = 88882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Zauberöl", progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt." }
quests[88883] = { id = 88883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Zauberöl", progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt." }
quests[88968] = { id = 88968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher von Blackrock", description = "Sucht Hochfürst Saurfang im Tal der Stärke auf.", sourceObjective = "Sprecht mit Hochfürst Saurfang in Orgrimmar. Er wartet im Tal der Stärke auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[88969] = { id = 88969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher von Blackrock", description = "Begebt Euch in das Tal der Helden und sprecht mit Feldmarschall Steinsteg.", sourceObjective = "Reist in Sturmwind in das Tal der Helden und sprecht mit Feldmarschall Steinsteg.", sourceObjectiveStatus = "unverified-source-field" }
quests[89224] = { id = 89224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensmittelmangel", description = "<Die Köchin spricht Euch an, bevor Ihr sie auch nur grüßen könnt.>\n\nDem Licht sei Dank, endlich kommt Hilfe! Weder der Ofen noch die Vorratskammer können mit der plötzlichen Masse an Bestellungen mithalten, die hereinströmen. Etwas ist passiert, das unsere Versorgungswege abgeschnitten hat, und ich schätze, das ganze Geschrei da draußen hat irgendetwas damit zu tun.\n\nWas auch immer der Grund ist, ich brauche Hilfe. Sofort. Bringt mir alles aus der Stadt, was irgendwie essbar aussieht, und dann sehen wir weiter.", sourceObjective = "Sammelt unappetitliche Überreste in Neu-Avalon und bringt sie der Köchin. Wenn Ihr Schwierigkeiten habt, sie aufzuspüren, könntet Ihr mehr Erfolg damit haben, den Engpass mit Gewalt zu lösen.", progress = "Lasst mich bitte in Ruhe, bis Ihr einige Zutaten gesammelt habt.", completion = "Oh. Oh... Ich hatte Brot vom Vortag, überreifes Obst und vielleicht einen Teller angeknabberter Kekse oder so erwartet.\n\nIch habe wirklich keine Ahnung, was das einmal für Gerichte waren. Und ich habe sie gekocht! Und dieser... Geruch... Wollt Ihr meine Küche sabotieren?\n\nTief durcharmen, Carrie...\n<Die Köchin schließt die Augen, atmet tief durch die Nase ein und kurz darauf langsam wieder aus.>\n\nVersuchen wir das noch einmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[89229] = { id = 89229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem rechten Pfad", description = "Nun kennt Ihr die ganze Geschichte. All das wiedererleben zu müssen, war schmerzhaft, aber ich habe es zu lange vor mir hergeschoben. Es geht mir... besser. So lange schon habe ich darum gebetet, dass Baelin Caldoran die Gerechtigkeit finden wird. Doch diese Gerechtigkeit auszuführen, ist nicht meine Bürde. Ich habe meinen eigenen Pfad gewählt, und indem ich mich von der Rache wieder ins Dunkel reißen lasse, werde ich weder Frieden finden, noch die Wünsche meines Sohnes ehren.\n\nIch begebe mich zurück und überreiche Lord Tyrosus meinen Bericht. Trefft mich in der Kapelle des hoffnungsvollen Lichts. Ich habe dort etwas für Euch.", sourceObjective = "Sprecht mit Leonid Barthalomew dem Geachteten an der Kapelle des hoffnungsvollen Lichts, um Eure Belohnung zu erhalten.", completion = "Caldoran wird seine Abrechnung erhalten, denn das Böse seiner Art neigt zur Selbstzerstörung. Daran glaube ich, wie ich an den Traum meines Sohnes glaube.\n\nBitte, nehmt das. Es wurde mir von Liliana überreicht, als ich von der Silbernen Hand aufgenommen wurde, und es diente mir während meiner Dienstjahre als Erinnerung an meinen Schwur gegenüber meiner Familie und meines Heimatlandes. Ich hoffe, es kann Euch als Erinnerung dienen, dass es vor der Dämmerung stets am dunkelsten ist. Doch die Dämmerung wird immer kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[89234] = { id = 89234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Angelegenheit", description = "Worüber wir in der Kapelle des hoffnungsvollen Lichts sprachen, und meine Geschichte mit Caldoran... Alles begann hier, in Stratholme. Ihr habt von dem \"Ausmerzen\" von Stratholme gehört, das zu Beginn des dritten Krieges stattfand?\n\nNun, ich war dort. Caldoran ebenfalls. Damals begann unsere gemeinsame Geschichte. Wenn Ihr gewillt seid, trefft mich vor dem Bediensteteneingang im Osten von Stratholme.", sourceObjective = "Trefft Euch mit Leonid Barthalomew dem Geachteten direkt beim Dienereingang östlich der Haupttore von Stratholme.", completion = "Ich bin froh, dass Ihr gekommen seid. Ich weiß nicht, ob ich den nächsten Schritt allein unternehmen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[89235] = { id = 89235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausmerzung", description = "Die Stadt hinter uns ist ein unheimlicher Ort. Nach meinem ersten Tod habe ich hier viele Jahre als Diener des Lichkönigs verbracht, doch selbst in meiner Knechtschaft behielt ich ein gewisses Maß meines Bewusstseins. Zahllose Male schlurfte ich an der Leiche meiner Frau vorüber, auf ewig in der Furcht gefroren, die sie verspürte, als das Ende kam.\n\nBegebt Euch bitte durch das Tor zu dem Bereich, der heute als der Schlächterplatz bekannt ist. Ich schließe zu Euch auf, sobald ich die Überwindung finde. Ihr werdet hierfür Verbündete brauchen.", sourceObjective = "Betretet Stratholme, geht durch das Tor, das zum Schlächterplatz führt, und findet dort Leonid Barthalomew den Geachteten.", completion = "Nun seht Ihr, warum ich Caldoran verachte. Er ist ein Mann von hasserfülltem Fanatismus. Das war er damals und das ist er heute. Caldoran hat Arthas' Expedition nach Nordend nicht begleitet, doch ich wünschte, er hätte es getan und nicht nur sein Ende dort gefunden, sondern auch das unserer gemeinsamen Geschichte.", sourceObjectiveStatus = "unverified-source-field" }
quests[89236] = { id = 89236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apfelbändiger", description = "Wenn Ihr mich fragt, ist frisches Obst der Höhepunkt jeder Mahlzeit. Äpfel habe ich am liebsten und praktischerweise gibt es südlich von hier eine ganze Plantage davon.\n\nVorausgesetzt, sie hat noch kein Feuer gefangen, was eine ernstzunehmende Möglichkeit ist, wäre es höchste Zeit für die Ernte!\n\nNormalerweise geben mir die Arbeiter dort einen Rabatt, aber ich schulde ihnen immer noch einen Kuchen. Ich werde sie also nicht billig bekommen, aber Ihr seht aus, als könntet Ihr sie Euch leisten.", sourceObjective = "Findet die Apfelplantage im Süden von Neu-Avalon und sammelt einige Äpfel. Kehrt zu Carrie Herdfeuer im Gasthaus von Neu-Avalon zurück, wenn Ihr Erfolg hattet. Wenn Ihr die Äpfel für zu teuer haltet, seht Euch nach alternativen Wegen um, sie zu bekommen.", progress = "Obwohl ich nur einen Steinwurf von einem Obstgarten entfernt wohne, ist es manchmal erstaunlich schwierig, an ein paar Äpfel zu kommen.", completion = "<Carrie untersucht jeden Apfel eindringlich auf Makel. Währenddessen herrscht eine lange, beklommene Stille.>\n\nIhr habt ein Auge für Qualität, wenn Ihr nicht gerade im Müll wühlt. Das sind die frischesten Äpfel, die ich seit meinen jungen Jahren im Kloster gesehen habe!\n\nIch muss zugeben, dass ich Euch nach Eurer ersten Lieferung fast die Mitgliedschaft entzogen hätte. Macht weiter so, dann biete ich Euch stattdessen vielleicht eine Vollzeitstelle an!", sourceObjectiveStatus = "unverified-source-field" }
quests[89245] = { id = 89245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fisch im Fass", description = "Ich habe eine Weile in Hearthglen gedient, und ich muss Euch sagen, wie absolut grauenerregend es war, darauf vertrauen zu müssen, dass die Vorratslieferungen über die Pestländer uns versorgen würden. Die stabile Versorgungskette über das Meer von Neu-Avalon war ein Segen, zumindest bis vor Kurzem.\n\nWir haben einen neuen Fall von \"Carrie versucht, in einer Küche, die für eine Familie ausgestattet ist, eine Armee zu versorgen\" und ich brauche Fisch. Seht am Dock südlich von hier nach, ob meine Bestellung angekommen ist.", sourceObjective = "Untersucht das Boot, das südlich von Neu-Avalon angelegt hat, auf die Fischlieferung und bringt Carrie eine Ladung davon.", progress = "Hatte ich schon erwähnt, dass ich Fischgeruch hasse? Vielleicht sollte ich Euch bitten, von unterwegs noch eine Wäscheklammer mitzubringen.", completion = "Ein paar davon kenne ich zwar nicht, aber Fisch ist Fisch, schätze ich. Jedenfalls freue ich mich schon auf den Moment, in dem das nicht mehr in meiner Küche ist.\n\nVielen Dank für Eure Hilfe, auch wenn ich insgeheim gehofft hatte, Ihr würdet mit leeren Händen zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[89253] = { id = 89253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptgericht", description = "Keine Mahlzeit ist wirklich komplett ohne den Star der Gerichts: Das Fleisch! Wie Ihr Euch bestimmt denken könnt, ist die Jagd nach genießbarem Fleisch in den Pestländern eine ganz gewaltige Herausforderung.\n\nUnd als wäre das nicht schlimm genug, fressen unsere Hunde ausschließlich Fleisch! Ich bin sicher, Ihr wisst schon, wie es weitergeht. Und ich bin sicher, Ihr versteht, warum ich permanent hinterher bin.\n\nUnd? Worauf wartet Ihr?", sourceObjective = "Besorgt Fleisch, das für Menschen genießbar ist. Wenn Ihr in Neu-Avalon keines findet, könnt Ihr bestimmt (irgendwann) von getöteten Tieren in den Östlichen Pestländern genug erbeuten.", progress = "Schon zurück? Das verheißt nichts Gutes.", completion = "Eure Zweckmäßigkeit ist ebenso willkommen wie verdächtig. Beinahe genauso verdächtig wie die Farbe dieser Fleischstücke. Zum Glück haben wir in unserer Zeit hier draußen alle starke Mägen entwickelt.\n\nHier ein paar Schnitte, da eine Gewürzprise und niemand wird etwas ahnen.\n\nDas wird hoffentlich reichen. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[89256] = { id = 89256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt, was Ihr könnt: Schulterschützer", description = "Immer auf dem neuesten Stand zu sein, ist wichtig, wenn man eine hohe Qualität beibehalten will. Unsere Soldaten vertrauen ihre Leben namenlosen Handwerkern an, und damit mir, denn ich stelle die Qualität jedes Rüstungsteils sicher.\n\nIch habe eine ganz simple Aufgabe für Euch: Wenn Ihr geübt in Schneiderei, Lederverarbeitung oder Schmiedekunst seid, dann stellt ein Paar Schulterschützer her, einfach für Euch selbst. Ihr könnt das Ergebnis behalten.\n\nWenn Euch das Können fehlt, dann könnt Ihr stattdessen ein beliebiges Stück der Uniform des Kreuzzugs in Auftrag geben und spenden.", sourceObjective = "Stellt scharlachrote Schulterstücke mit einem beliebigen Handwerksberuf her oder spendet ein beliebiges Teil einer Scharlachroten Uniform.\n\nWenn Ihr etwas spenden wollt, könnt Ihr eine Kiste in der Nähe des Rüstmeisters in der Kaserne finden. Bringt das Ausrüstungsteil zu Bryon Steelblade, um Anerkennung zu erhalten.", progress = "Stellt selbst etwas her oder spendet etwas, die Wahl liegt bei Euch. Unsere Waffenkammer ist prall gefüllt und wir sind auf das Schlimmste vorbereitet, aber das Wichtigste ist, dass unsere Handwerker genug Gelegenheit zum Üben und Verfeinern ihrer Technik haben.", completion = "Ausgezeichnete Arbeit.\n\nWir haben damit begonnen, konfiszierten Schrott in diesen alten Truhen zu lagern, aber langsam geht mir der Platz hier aus. Ihr seht mir wie jemand aus, der Wert auf die kleinen Dinge im Leben legt. Für Euren kleinen Beitrag dürfte dies eine angemessene Belohnung sein.\n\nOh, und einige davon enthalten eine kostbare Überraschung. Vielleicht ist das Glück Euch ja hold?", sourceObjectiveStatus = "unverified-source-field" }
quests[89257] = { id = 89257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt, was Ihr könnt: Brustschutz", description = "Immer auf dem neuesten Stand zu sein, ist wichtig, wenn man eine hohe Qualität beibehalten will. Unsere Soldaten vertrauen ihre Leben namenlosen Handwerkern an, und damit mir, denn ich stelle die Qualität jedes Rüstungsteils sicher.\n\nIch habe eine ganz simple Aufgabe für Euch: Wenn Ihr geübt in Schneiderei, Lederverarbeitung oder Schmiedekunst seid, dann stellt einen Brustschutz her, einfach für Euch selbst. Ihr könnt das Ergebnis behalten.\n\nWenn Euch das Können fehlt, dann könnt Ihr stattdessen ein beliebiges Stück der Uniform des Kreuzzugs in Auftrag geben und spenden.", sourceObjective = "Stellt einen scharlachroten Brustharnisch mit einem beliebigen Handwerksberuf her oder spendet ein beliebiges Teil einer Scharlachroten Uniform.\n\nWenn Ihr etwas spenden wollt, könnt Ihr eine Kiste in der Nähe des Rüstmeisters in der Kaserne finden. Bringt das Ausrüstungsteil zu Byron Steelblade, um Anerkennung zu erhalten.", progress = "Stellt selbst etwas her oder spendet etwas, die Wahl liegt bei Euch. Unsere Waffenkammer ist prall gefüllt und wir sind auf das Schlimmste vorbereitet, aber das Wichtigste ist, dass unsere Handwerker genug Gelegenheit zum Üben und Verfeinern ihrer Technik haben.", completion = "Ausgezeichnete Arbeit.\n\nWir haben damit begonnen, konfiszierten Schrott in diesen alten Truhen zu lagern, aber langsam geht mir der Platz hier aus. Ihr seht mir wie jemand aus, der Wert auf die kleinen Dinge im Leben legt. Für Euren kleinen Beitrag dürfte dies eine angemessene Belohnung sein.\n\nOh, und einige davon enthalten eine kostbare Überraschung. Vielleicht ist das Glück Euch ja hold?", sourceObjectiveStatus = "unverified-source-field" }
