quests[89262] = { id = 89262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt, was Ihr könnt: Stiefel", description = "Immer auf dem neuesten Stand zu sein, ist wichtig, wenn man eine hohe Qualität beibehalten will. Unsere Soldaten vertrauen ihre Leben namenlosen Handwerkern an, und damit mir, denn ich stelle die Qualität jedes Rüstungsteils sicher.\n\nIch habe eine ganz simple Aufgabe für Euch: Wenn Ihr geübt in Schneiderei, Lederverarbeitung oder Schmiedekunst seid, dann stellt ein Paar Schuhe her, einfach für Euch selbst. Ihr könnt das Ergebnis behalten.\n\nWenn Euch das Können fehlt, dann könnt Ihr ein beliebiges Stück der Uniform des Kreuzzugs in Auftrag geben und es stattdessen spenden.", sourceObjective = "Stellt scharlachrote Stiefel mit einem beliebigen Handwerksberuf her oder spendet ein beliebiges Teil einer Scharlachroten Uniform.\n\nWenn Ihr etwas spenden wollt, könnt Ihr eine Kiste in der Nähe des Rüstmeisters in der Kaserne finden. Bringt das Ausrüstungsteil zu Byron Steelblade, um Anerkennung zu erhalten.", progress = "Stellt selbst etwas her oder spendet etwas, die Wahl liegt bei Euch. Unsere Waffenkammer ist prall gefüllt und wir sind auf das Schlimmste vorbereitet, aber das Wichtigste ist, dass unsere Handwerker genug Gelegenheit zum Üben und Verfeinern ihrer Technik haben.", completion = "Ausgezeichnete Arbeit.\n\nWir haben damit begonnen, konfiszierten Schrott in diesen alten Truhen zu lagern, aber langsam geht mir der Platz hier aus. Ihr seht mir wie jemand aus, der Wert auf die kleinen Dinge im Leben legt. Für Euren kleinen Beitrag dürfte dies eine angemessene Belohnung sein.\n\nOh, und einige davon enthalten eine kostbare Überraschung. Vielleicht ist das Glück Euch ja hold?", sourceObjectiveStatus = "unverified-source-field" }
quests[89310] = { id = 89310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckenstal", description = "Es dauerte viele Jahre, bis ich mich von meiner Schuld erholen konnte, nachdem mein Geist aus den Fesseln des Lichkönigs gelöst wurde. Nachdem Sylvanas mich befreite, lehnte ich das Angebot der Dunklen Fürstin ab und ging allein in die Pestländer. Ich wanderte monatelang, ziellos. Ich bin nicht sicher, wie es dazu kam, aber letztendlich zog es mich zum Zuhause meiner Familie zurück, und was ich dort fand, war... unerwartet.\n\nReist zum Geisterdorf Schreckenstal und trefft mich dort im nördlichsten Haus. Dort werdet Ihr alles erfahren.", sourceObjective = "Reist nach Schreckenstal und findet Leonid Barthalomew in einem der Häuser dort.", completion = "Es widert mich an, wozu mein Heim verkommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[89328] = { id = 89328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlust", description = "Ihr könnt Euch sicher vorstellen, wie überrascht ich war, als ich ihn nach all den Jahren des ziellosen Herumirrens hier fand, vor allem lebendig und wohlauf. Im Gegensatz zu den anderen Lebenden verstieß er mich nicht, sondern hieß mich willkommen. Er war ein Heiler geworden, der die Untoten studierte, und er war überzeugt, dass er ein Heilmittel finden könnte, um den Untod nicht nur zu verhindern, sondern ihn sogar rückgängig machen zu können. \n\nFür kurze Zeit waren wir zusammen und glücklich. Ich half meinem Sohn bei seinen Forschungen, und er gab mir die Hoffnung, die ich brauchte.\n\nZumindest bis Baelin Caldoran sich wieder in unser Leben einmischte.", sourceObjective = "Hört Euch das Ende von Leonids Geschichte an.", completion = "Zu meiner Schande habe ich überlebt. Es hat nicht lange gedauert, bis Lord Tyrosus mich fand und wieder zusammenflickte.\n\nZweimal war Baelin Caldoran verantwortlich für den Tod von jemandem, der mir sehr nahe stand. Seine Art von überheblichem Eifer und Fanatismus bezeichnet das Herz der Korruption, die den Scharlachroten Kreuzzug plagt.\n\nIch werde mich nie mehr von dem Schmerz erholen, doch ich ehre meinen Sohn, indem ich seine Hoffnung und Vision für eine Zukunft forttrage, in der der Fluch des Untods geheilt werden kann. Ich muss hoffen, dass eines Tages jemand die Arbeit meines Sohnes vollenden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[89329] = { id = 89329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Befall niederstampfen", description = "Widerwärtig. Dieser Ort ist von verrottenden Neruberdrohnen befallen. Sie sollten vernichtet werden.", sourceObjective = "Erschlagt 5 Gruftwandler und 8 Gruftbestien und kehrt dann zu Leonid Barthalomew dem Geachteten in seinem ehemaligen Zuhause im Schreckenstal zurück.", completion = "Es ist höchstwahrscheinlich nur eine bedeutungslose Geste, aber ich fühle mich wenigstens ein winziges Bisschen besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[89340] = { id = 89340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bescheuert beschrifteter Brief", description = "An die verehrte Chefköchin von Neu-Avalon, Carrie Herdfeuer. \n\nIch hoffe, dieser Brief erreicht Euch frohen Mutes! Eure Abreise aus Hearthglen hinterließ eine große Leere in unseren Herzen und unseren Bäuchen. Es vergeht kein Tag ohne Beschwerde über den Haferbrei und die Sehnsucht nach der nächsten köstlichen Mahlzeit.\n\nDaher planen wir ein Bankett, eines, auf dem wir nur die besten Gerichte von ganz Lordaeron servieren: Eure.\n\nEine bewachte Karawane wird in zwei Wochen eintreffen, damit Ihr und Eure Gerichte bestmöglich vorbereitet seid.", sourceObjective = "Überbringt die letzte Lieferung.", completion = "<Carrie nimmt auf Euer Drängen hin endlich den Brief und überfliegt den Inhalt. Ihre Augen werden groß.>\n\nWie soll ich für ein ganzes Bataillon des Scharlachroten Kreuzzugs die Zutaten sammeln und Mahlzeiten zubereiten? Und dazu noch in nur zwei Wochen? Das kommt wirklich zur schlechtesten Zeit.\n\nSo oder so, die Bürger von Neu-Avalon gehen vor. Bis dahin muss ich wohl auf eine helfende Hand hoffen.\n\n<Sie macht eine Pause.>\n\nMoment, warum war der schon geöffnet?", sourceObjectiveStatus = "unverified-source-field" }
quests[89341] = { id = 89341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Festmahl", description = "Eure Unterstützung ist unbezahlbar. Die Bürger und Soldaten von Neu-Avalon können sich heute Abend und viele weitere Abende auf ein warmes Essen freuen. Ich danke Euch von Herzen.\n\nDoch wie Ihr offensichtlich selbst gelesen habt, muss ich mich noch um eine weitere Aufgabe kümmern, bevor ich die Füße hochlegen kann. Das meiste davon schaffe ich selbst, aber wenn Ihr mir noch einen Gefallen tun möchtet, würde ich Euch zum Lohn meine berühmtesten Rezepte beibringen.\n\nIhr werdet jeden Abend wie ein Hochlord speisen.", sourceObjective = "Helft Carrie Herdfeuer in Neu-Avalon ein letztes Mal, indem Ihr die folgenden Zutaten sammelt:", progress = "Ah, wie schön Euch wiederzusehen! Habt Ihr die letzte Zutatenlieferung dabei, die ich brauche?", completion = "Schnell und zuverlässig wie immer. Ich hätte nie an Euch zweifeln dürfen. Lasst mich Euch das abnehmen.\n\nIch weiß zwar noch immer nicht, was Euch dazu antreibt, aber Ihr habt auf jeden Fall ein gütiges Herz. Wie versprochen habt Ihr hier mein Kochbuch. Ich brauche es nicht mehr, ich kenne alle meine Rezepte schon lange auswendig!\n\nDanke vielmals, kommt jederzeit wieder vorbei!\n\n<Carrie schenkt Euch ein aufrichtiges, entspanntes Lächeln und macht sich wieder an die Arbeit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[89342] = { id = 89342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "VIP-Mitgliedschaft im Gourmetclub", description = "He, Ihr da!\n\nIhr seht aus, wie die Person, von der Carrie in letzter Zeit so viel redet. Sie hat nur Gutes über Euch gesagt. Nun, anfangs noch nicht, aber sie hat schnell ihre Meinung geändert.\n\nWie auch immer, Freunde der Köchin sind auch meine Freunde. Ich möchte Euch eine dauerhafte Mitgliedschaft anbieten, dann müsst Ihr auch diese Karte nicht immer herumtragen.\n\nAls Gegenleistung bitte ich Euch nur um ein Morgengrauenomelett und ein Pirschersteak. Beides von Euch zubereitet, versteht sich.", sourceObjective = "Bereitet eigenhändig ein Morgengrauenomelett und ein Pirschersteak zu und serviert beides Devon Woods vor dem Gasthaus von Neu-Avalon.", progress = "Habt Ihr mein Essen?", completion = "<Ohne Umschweife nimmt er einen Bissen von beiden Gerichten.>\n\nOha, Carrie hat Konkurrenz. Sie muss Euch alle ihre Techniken beigebracht haben. Das überrascht mich, ich konnte sie nie dazu bewegen, mir irgendetwas beizubringen.\n\nDanke. Ich habe Euren Namen bereits zu den permanenten VIP-Gästen unserer Einrichtung hinzugefügt. Ihr könnt von nun an kommen und gehen, wie es Euch beliebt, und ganz ohne Mitgliedskarte. Vorausgesetzt, Ihr tut nichts, was unsere Gäste verschrecken könnte.", sourceObjectiveStatus = "unverified-source-field" }
